(window.GIM_TS=window.GIM_TS||{})["Nedarim.5"]={"from":120,"a":[["\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הוקפלו רוב המקצועות,\u0004 כלומר, הוחזרו למקומם הסכינים שקוצצים בהן את התאנים — \u0003מותרות\u0004 התאנים הנמצאות בשדה \u0003משום גזל,\u0004 שאין הבעלים מקפידים עוד עליהן, \u0003ופטורות מן המעשרות\u0004 משום שהן הפקר.","מסופר: \u0003רבי ור' יוסי בר ר' יהודה איקלעו לההוא אתרא\u0004 \u0005[הזדמנו למקום אחד]\u0006 \u0003בזמן שהוקפלו רוב המקצועות, רבי הוא קא אכיל\u0004 \u0005[היה אוכל]\u0006 מהן, \u0003ר' יוסי בר ר' יהודה לא אכיל\u0004 \u0005[אכל].\u0006 \u0003אתא מרהון\u0004 \u0005[בא בעליהן]\u0006 של התאנים, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמאי לא אכלי רבנן\u0004 \u0005[מדוע אין חכמים אוכלים]?\u0006 הלא זמן שבו \u0003הוקפלו רוב המקצועות הוא! ואף על פי כן לא אכיל\u0004 \u0005[אכל]\u0006 \u0003ר' יוסי בר ר' יהודה, קסבר\u0004 \u0005[היה סבור]:\u0006 \u0003משום סניות מילתא הוא דקאמר הדין גברא\u0004 \u0005[בגלל בושה\u0006 שב\u0005דבר הוא שאמר\u0006 כן \u0005אותו אדם]\u0006 ולא התכוון באמת להפקירן.","מסופר: \u0003ר' חמא בר ר' חנינא איקלע לההוא אתרא\u0004 \u0005[הזדמן למקום אחד]\u0006 \u0003בזמן שהוקפלו רוב המקצועות, הוה קאכיל\u0004 \u0005[היה אוכל]\u0006 מן התאנים, \u0003יהיב לשמעיה\u0004 \u0005[נתן לשמשו]\u0006 ו\u0003לא אכיל\u0004 \u0005[אכל]\u0006 השמש. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אכול, כך אמר לי ר' ישמעאל בר ר' יוסי משום\u0004 (בשם) \u0003אביו: הוקפלו רוב המקצועות —\u0004 \u0003מותרות משום גזל ופטורות מן המעשר.\u0004","מסופר: \u0003ר' טרפון אשכחיה ההוא גברא\u0004 \u0005[מצא אותו אדם אחד]\u0006 בעל שדה \u0003בזמן שהוקפלו המקצועות דקאכיל\u0004 \u0005[שהיה אוכל]\u0006 מן התאנים. \u0003אחתיה בשקא ושקליה ואמטייה למשדיה בנהרא\u0004 \u0005[הכניס אותו בשק ונטלו והביאו עאל מנת לזרוק אותו בנהר].\u0006 \u0003אמר לו\u0004 ר' טרפון: \u0003אוי לו לטרפון שזה הורגו! שמע ההוא גברא שבקיה וערק\u0004 \u0005[אותו אדם, הניחו וברח]\u0006 שנבהל והתבייש על שרצה לפגוע באדם גדול כר' טרפון. \u0003אמר ר' אבהו משום\u0004 (בשם) \u0003ר' חנניה בן גמליאל: כל ימיו של אותו צדיק\u0004 (ר' טרפון) \u0003היה מצטער על דבר זה, אמר: אוי לי שנשתמשתי בכתרה של תורה,\u0004 שמשום כבוד תורתו של ר' טרפון הניח לו אותו אדם.","\u0003ו\u0004באותו ענין \u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל המשתמש בכתרה של תורה נעקר מן העולם.\u0004 ואפשר ללמוד זאת מ\u0003קל וחומר: ומה בלשצר שנשתמש בכלי קודש\u0004 של מקדש \u0003ש\u0004באותה שעה \u0003נעשו\u0004 כבר \u0003כלי חול,\u0004 שלאחר שהוצאו בכוח מן המקדש נתחללה קדושתם, וראיה שנתחללו — \u0003שנאמר: \"ובאו בה פריצים וחללוה\"\u0004 (יחזקאל ז, כב), לומר: \u0003כיון שפרצום נעשו חול,\u0004 ובכל זאת, מפני שעשה בלשצר כן \u0003נעקר מן העולם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בה בליליא קטיל בלאשצר\"\u0004 \u0005[בו בלילה נהרג בלשצר]\u0006 (דניאל ה, ל), \u0003המשתמש בכתרה של תורה שהוא חי וקיים\u0004 ואינו מתחלל \u0003לעולם —\u0004 \u0003על אחת כמה וכמה.\u0004","ושואלים: \u0003ור' טרפון, כיון דכי אכיל\u0004 \u0005[שכאשר אכל]\u0006 בזמן ש\u0003הוקפלו רוב המקצועות הוה\u0004 \u0005[היה],\u0006 \u0003אמאי צעריה ההוא גברא\u0004 \u0005[מדוע ציערו אותו אדם]?\u0006 ומסבירים: \u0003משום דההוא הוו גנבי ליה ענבי כולה שתא\u0004 \u0005[שאותו\u0006 אדם \u0005היו גונבים לו ענבים כל השנה],\u0006 \u0003וכיון דאשכחיה\u0004 \u0005[שמצאו]\u0006 \u0003לר' טרפון סבר\u0004 \u0005[חשב]:\u0006 \u0003היינו דגנבן\u0004 \u0005[זהו שגנב ממני]\u0006 כל השנה. ושואלים: \u0003אי הכי אמאי ציער נפשיה\u0004 \u0005[אם כך מדוע ציער\u0006 ר' טרפון את \u0005עצמו]?\u0006 הלא ידע שאין הוא הגנב והיה צריך להציל עצמו! ומשיבים: \u0003משום\u0004 ש\u0003ר' טרפון עשיר גדול הוה\u0004 \u0005[היה],\u0006 \u0003ו\u0004על מנת להינצל \u0003הוה ליה\u0004 \u0005[והיה לו]\u0006 \u0003לפייסו בדמים\u0004 (בכסף), ולא לומר לו שהוא ר' טרפון. כיון שהוזכר המעשה שר' טרפון הצטער על שנשתמש בכתרה של תורה, מביאים דברים נוספים הקרובים לאותו נושא.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 נאמר \u0003\"לאהבה את ה' אלהיך לשמע בקלו ולדבקה בו\"\u0004 (דברים ל, כ) ובא הדבר להדגיש \u0003שלא יאמר אדם: אקרא\u0004 בתורה כדי \u0003שיקראוני \"חכם\", אשנה\u0004 במשנה כדי \u0003שיקראוני \"רבי\", אשנן\u0004 כדי \u0003שאהיה זקן\u0004 (חכם, רב) \u0003ואשב בישיבה.\u0004","\u0003אלא למד מאהבה\u0004 כפי שאמר הכתוב \"לאהבה את ה'\", \u0003וסוף הכבוד לבא\u0004 מעצמו. \u0003שנאמר: \"קשרם על אצבעתיך כתבם על לוח לבך\"\u0004 (משלי ז, ג). \u0003ואומר: \"דרכיה דרכי נעם\u0004 וכל נתיבותיה שלום\u0003\"\u0004 (משלי ג, יז). \u0003ואומר: \"עץ חיים היא למחזיקים בה ותמכיה מאשר\"\u0004 (משלי ג, יח), שהמחזיק בתורה לשם שמים סופו שיזכה לעושר וכבוד, שלום ואושר גם בעולם הזה.","\u0003ר' אליעזר בר ר' צדוק אומר: עשה דברים לשם פעלם,\u0004 לשם עצמם, ולא לשם מטרה אחרת, \u0003ודבר בהם לשמם. אל תעשם\u0004 את דברי התורה \u0003עטרה\u0004 וכבוד כדי \u0003להתגדל בהם, ואל תעשם קורדום להיות עודר בו,\u0004 כלומר, לכלי להתפרנס מהם. \u0003וקל וחומר: ומה בלשצר שלא נשתמש אלא בכלי קדש שנעשו כלי חול —\u0004 \u0003נעקר\u0004 בשל כך \u0003מן העולם, המשתמש בכתרה של תורה\u0004 שאינם מתחללים לעולם — \u0003על אחת כמה וכמה.\u0004","\u0003אמר רבא:\u0004 בשעת הצורך \u0003שרי ליה לאיניש לאודועי נפשיה באתרא דלא ידעי ליה\u0004 \u0005[מותר לו לאדם להודיע,\u0006 לפרסם \u0005עצמו במקום שאין מכירים אותו],\u0006 וראיה לדבר — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר עובדיהו לאליהו, כדי שידע מי הוא \u0003\"ועבדך ירא את ה' מנערי\"\u0004 (מלכים א יח, יב). ושואלים: \u0003אלא קשיא\u0004 \u0005[קשה]\u0006 זו של \u0003ר' טרפון\u0004 שהצטער על מה שאמר לאותו אדם שהכניסו לשק, והרי הלה לא הכירו, ומותר היה לו להודיע מי הוא! ומשיבים: שונה המקרה של ר' טרפון כיון ש\u0003עשיר גדול היה, והוה ליה לפייסיה\u0004 \u0005[והיה לו לפייסו]\u0006 \u0003בדמים.\u0004","\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ועבדך ירא את ה' מנערי\", וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"יהללך זר ולא פיך\"\u0004 (משלי כז, ב)! ותירץ: \u0003הא\u0004 \u0005[זה] —\u0006 \u0003באתרא דידעי ליה\u0004 \u0005[במקום שמכירים אותו]\u0006 אין לו להלל את עצמו, \u0003הא\u0004 \u0005[זה] —\u0006 \u0003באתרא דלא ידעי ליה\u0004 \u0005[במקום שאין יודעים אותו].\u0006","\u0003אמר רבא: שרי לצורבא מרבנן למימר\u0004 \u0005[מותר לתלמיד חכם לומר]:\u0006 \u0003צורבא מרבנן אנא, שרו לי תיגראי ברישא\u0004 \u0005[תלמיד חכם אני, פתרו את דיני בראשונה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובני דוד כהנים היו\"\u0004 (שמואל ב ח, יח), והרי בודאי לא היו כהנים ממש, אלא ודאי כוונתו: \u0003מה כהן נוטל בראש —\u0004 \u0003אף תלמיד חכם נוטל בראש. וכהן מנא לן\u0004 \u0005[מניין לנו]\u0006 שהוא נוטל חלק בראש? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וקדשתו כי את לחם (ה') אלהיך הוא מקריב\"\u0004 (ויקרא כא, ח), \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: \"וקדשתו\" —\u0004 \u0003לכל דבר שבקדושה\u0004 צריך לקדשו,"],["\u0003לפתוח\u0004 ולקרוא בספר תורה \u0003ראשון, ולברך ראשון\u0004 שהוא קודם לאחרים כשמכבדים אנשים לברך ברכה על האוכל וכיוצא בה, \u0003וליטול מנה יפה ראשון,\u0004 שאם מתחלק שווה בשווה עם אחר במנות, יכול הכהן לבחור איזו מנה שירצה. ומן האמור בבני דוד ראיה שאף תלמיד חכם קודם לכל אדם בעניינים שונים.","באותו ענין \u0003אמר רבא: שרי ליה לצורבא מרבנן למימר\u0004 \u0005[מותר לו לתלמיד חכם לומר]:\u0006 \u0003לא יהיבנא אכרגא\u0004 \u0005[אין אני נותן את מיסי הקרקע],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במכתב שנתן מלך פרס בידי עזרא \u0003\"מנדה בלו והלך לא שליט למרמא עליהום\"\u0004 \u0005[\"מנדה בלו והלך אין רשות להטיל עליהם\"]\u0006 על הכהנים והלוויים ושאר עובדי המקדש (עזרא ז, כד). \u0003ואמר ר' יהודה: \"מנדה\" —\u0004 \u0003זו מנת\u0004 (מס) \u0003המלך, \"בלו\" —\u0004 \u0003זו כסף גולגלתא\u0004 \u0005[הגולגולת],\u0006 מס המוטל על כל אדם לפי הגולגולת, \u0003ו\"הלך\" —\u0004 \u0003זו ארנונא,\u0004 מס של עבודת כפייה על האדם ובהמותיו לצורך השלטונות.","\u0003ו\u0004עוד \u0003אמר רבא\u0004 על המותר לתלמיד חכם לומר כדי שלא יצטרך לשלם מיסים: \u0003שרי ליה לצורבא מרבנן למימר\u0004 \u0005[מותר לו לתלמיד חכם לומר]:\u0006 \u0003\"עבדא דנורא אנא לא יהיבנא אכרגא\u0004 \u0005[עבד האש אני\u0006 ו\u0005איני נותן את מס הקרקע]\u0006 \u0003\".\u0004 שכהני האש היו פטורים ממיסים, ויכול תלמיד חכם להשתמש בביטוי זה משום שבליבו הוא מתכוון לשמים (שהרי נאמר על ה' שהוא \"אש אוכלה\"), אלא שמטעה בכך את גובה המס. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 התירו לומר דבר כגון זה — \u0003לאברוחי אריא מיניה קאמר\u0004 \u0005[להבריח אריה ממנו\u0006 בלבד הוא \u0005אומר\u0006 זאת\u0005],\u0006 כלומר, כדי למנוע מעצמו נזק.","\u0003רב אשי הוה ליה ההוא אבא\u0004 \u0005[היה לו יער אחד],\u0006 \u0003זבניה לבי נורא\u0004 \u0005[מכר אותו\u0006 לכריתת עציו \u0005לבית\u0006 כהני \u0005האש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: האיכא\u0004 \u0005[הרי יש\u0006 כאן\u0005]\u0006 משום \u0003\"\u0004ו\u0003לפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד), שהרי אתה מסייע בכך לפולחן עבודה זרה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רוב עצים,\u0004 ואף אותם הנמכרים לכהני האש, \u0003להסקה ניתנו\u0004 ולא לפולחן, ולכן אין עליו לחשוש שמא העצים האלה מיועדים דווקא לצורך זה.","נדר \u0003\"עד הקציר\"\u0004 — כוונתו \u0003עד שיתחיל העם לקצור,\u0004 וכוונתו \u0003קציר חטין אבל לא קציר שעורין,\u0004 וקובעים זמן זה \u0003הכל לפי מקום נדרו. אם היה בהר —\u0004 לפי הקוצרים \u0003בהר, ואם היה בבקעה\u0004 — לפי הקוצרים \u0003בבקעה.\u0004","אמר \u0003\"עד הגשמים\"\u0004 או \u0003\"עד שיהו הגשמים\",\u0004 כוונתו \u0003עד שתרד רביעה\u0004 (עונה) \u0003שניה\u0004 של גשמים. \u0003רבן שמעון בן גמליאל אומר: עד שיגיע זמנה של רביעה,\u0004 שאינו צריך להמתין לגשמי הרביעה השניה ממש, אלא כשמגיע הזמן הראוי לכך, זהו הזמן שקבע לנדר. אמר \u0003\"עד שיפסקו גשמים\"\u0004 — הרי זה אסור \u0003עד שיצא\u0004 חודש \u0003ניסן כולו,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: עד שיעבור הפסח.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הנודר \"עד הקיץ\" בגליל, וירד לעמקים, אף על פי שהגיע\u0004 כבר זמן \u0003הקיץ בעמקים —\u0004 \u0003אסור\u0004 עוד \u0003עד שיגיע הקיץ בגליל,\u0004 שכאמור במשנה זמן הנדר נקבע לפי המקום שנדר בו.","שנינו במשנה: אמר \u0003\"עד הגשמים\"\u0004 או \u0003\"עד שיהו גשמים\"\u0004 — הרי זה אסור \u0003עד שתרד רביעה שניה, רבן שמעון בן גמליאל אומר:\u0004 לא עד שירד הגשם ממש, אלא עד הזמן הראוי לכך. \u0003אמר ר' זירא: מחלוקת\u0004 כש\u0003אמר \"עד הגשמים\", אבל\u0004 אם \u0003אמר \"עד הגשם\"\u0004 — לדברי הכל \u0003עד זמן גשמים קאמר\u0004 \u0005[אומר\u0006 הוא\u0005]\u0006 ואין כוונתו לזמן ירידת גשמים ממש."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003איזוהי זמנה של רביעה? הבכירה\u0004 אם הרביעה מקדימה — הרי היא \u0003בשלשה\u0004 במרחשון, \u0003בינונית\u0004 מגיעה \u0003בשבעה\u0004 בו, \u0003אפילה\u0004 (מאוחרת) — \u0003בעשרים ושלשה\u0004 בו, אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 התאריכים הם: \u0003בשבעה, ובשבעה עשר, ובעשרים ושלשה\u0004 במרחשון.","\u0003ר' יוסי אומר: בשבעה עשר, ובעשרים ושלשה\u0004 במרחשון, \u0003ו\u0004המאוחרת \u0003בחודש כסליו. וכן היה ר' יוסי אומר: אין היחידים\u0004 (תלמידי חכמים) \u0003מתענין\u0004 על עצירת הגשמים \u0003עד שיגיע ראש חדש כסליו\u0004 ולא ירדו גשמים.","\u0003ואמרינן עלה\u0004 \u0005[ואמרנו עליה]\u0006 : \u0003בשלמא\u0004 \u0005[נניח]\u0006 שנחלקו בזמן \u0003רביעה ראשונה —\u0004 יש לכך משמעות הלכתית \u0003לישאל,\u0004 כלומר, לזמן בו מתחילים להתפלל על הגשם בברכת השנים. וכן רביעה \u0003שלישית\u0004 צריכים לקבוע לה זמן — כדי לדעת מתי מתחילים \u0003להתענות\u0004 על עצירת הגשמים. \u0003אלא שניה למאי\u0004 \u0005[למה]\u0006, לאיזה צורך דנו בדבר? \u0003ואמר ר' זירא: לנודר\u0004 ותולה את נדרו בגשם.","\u0003ואמרינן עלה\u0004 \u0005[ואמרנו על כך]\u0006 : \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת\u0006 שיטה \u0005זו ששנינו\u0006 בברייתא\u0005]\u0006, \u0003רבן שמעון בן גמליאל אומר: גשמים שירדו שבעה ימים זה אחר זה —\u0004 \u0003אתה מונה בהן רביעה ראשונה ושניה\u0004 כיון שירדו סמוכים זה לזה. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 היא\u0005]\u0006? \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 כי הוא התנא היחיד החושב את ההפסק בין רביעה ראשונה לשניה כשבעה ימים. ומכל מקום רואים שדעת רבן שמעון בן גמליאל שהנודר עד לגשם צריך להמתין עד אחר רביעה שניה וירידת הגשם בפועל, ובניגוד למה שאמר ר' זירא שלדעתו אם נדר \"עד הגשם\" הרי זה זמן הגשם!","ומשיבים: \u0003ההוא\u0004 באותה ברייתא מדובר ש\u0003אמר\u0004 הנודר \u0003\"עד הגשמים\",\u0004 ולא \"עד הגשם\", ומשום כך צריך לקבוע את הזמן לפי ירידת הגשמים בפועל.","אמר \u0003\"קונם יין שאיני טועם לשנה\u0004 זו \u0003\",\u0004 אם \u0003נתעברה השנה —\u0004 \u0003אסור בה ובעיבורה\u0004 (בחודש הנוסף, חודש העיבור). אם נדר ואמר בנדרו \u0003\"עד ראש אדר\"\u0004 כוונתו \u0003עד ראש אדר הראשון,\u0004 וכן אם אמר \u0003\"עד סוף אדר\" —\u0004 כוונתו \u0003עד סוף אדר הראשון.\u0004","שנינו במשנה שהנודר עד ראש אדר או סוף אדר, הרי זה אדר הראשון. ומכאן מסיקים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003סתמא ד\"אדר\" דקאמר\u0004 \u0005[סתם \"אדר\" ש\u0006אדם \u0005אומר]\u0006 — \u0003ראשון הוא.\u0004","ומעירים: \u0003לימא מתניתין\u0004 \u0005[האם לומר\u0006 ש\u0005משנתנו]\u0006 כשיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 : בחודש \u0003אדר הראשון כותב\u0004 בשטרות את התאריך \u0003\"אדר הראשון\",\u0004 וב\u0003אדר שני כותב \"אדר\" סתם,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר\u0004 להיפך: \u0003אדר הראשון כותב סתם,\u0004 וב\u0003אדר שני כותב \"תיניין\"\u0004 \u0005[שני]\u0006. ולכאורה משנתנו האומרת שסתם אדר הוא אדר ראשון היא כדעת ר' יהודה.","\u0003אמר אביי: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' מאיר,\u0004 יש לחלק: \u0003הא\u0004 \u0005[זה],\u0006 בברייתא — \u0003דידע דמעברא שתא\u0004 \u0005[שיודע שמעוברת השנה]\u0006 ובזה נחלקו, שר' מאיר סבור שאדר השני הוא אדר העיקרי, \u0003הא\u0004 \u0005[זה],\u0006 במשנה שלנו — \u0003דלא ידע\u0004 \u0005[שאינו יודע]\u0006, ומכיון שלא ידע אין אומרים שייאסר אלא במה שהיה ידוע לו מראש."],["\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]\u0006 : האומר \u0003\"עד ראש חדש אדר\" —\u0004 כוונתו \u0003עד ראש חדש אדר הראשון, אם היתה שנה מעוברת — כוונתו\u0004 \u0003עד ראש חדש אדר השני.\u0004","ויש לתמוה: האם \u0003מכלל\u0004 הדברים אתה לומד \u0003דרישא\u0004 \u0005[ש\u0006ב\u0005תחילתה\u0006 של הברייתא\u0005]\u0006 \u0003לאו ב\u0004שנה \u0003מעוברת עסקינן\u0004 \u0005[עוסקים אנו]\u0006?! והרי בשנה שאינה מעוברת אין שני חודשי אדר, ואין כלל מקום לשאלה למה היתה כוונתו! אלא \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דפשיטא ליה דמעברא שתא\u0004 \u0005[שפשוט לו שמעוברת השנה]\u0006 ואז כשאומר \"אדר\" כוונתו לאדר השני, \u0003הא\u0004 \u0005[זה] —\u0006 ש\u0003לא ידע\u0004 ששנה זו מעוברת, מניחים אנו כי כוונתו לאדר הראשון, והרי זה סיוע למה שאמרנו קודם, שיש לחלק בין יודע בעיבור השנה לשאינו יודע.","\u0003ר' יהודה אומר:\u0004 האומר \u0003\"קונם יין שאיני טועם עד שיהא הפסח\" —\u0004 \u0003לא נתכוון זה\u0004 לאסור את עצמו \u0003אלא עד ליל הפסח, עד שעה שדרך בני אדם\u0004 מישראל \u0003לשתות יין\u0004 למצוות ארבע כוסות.","וכן אם \u0003אמר \"קונם בשר שאיני טועם עד שיהא הצום\"\u0004 (יום הכיפורים) — \u0003אינו אסור אלא עד לילי צום,\u0004 כלומר, עד ליל אותו יום שבו הוא מתחיל לצום, \u0003שלא נתכוון זה אלא עד שעה שדרך בני אדם לאכול בשר\u0004 בערב יום הכיפורים, שמצוה להרבות בו באכילה ושתיה. \u0003ר' יוסי בנו\u0004 של ר' יהודה \u0003אומר:\u0004 האומר \u0003\"קונם שום שאני טועם עד שתהא שבת\" —\u0004 \u0003אינו אסור אלא עד לילי שבת, שלא נתכוון זה אלא עד שעה שדרך בני אדם לאכול בשום.\u0004","\u0003האומר לחבירו \"קונם\u0004 (מה) \u0003שאני נהנה לך\u0004 (ממך) \u0003אם אין את בא ונוטל לבניך\u0004 כמתנה \u0003כור אחד של חטין ושתי חביות של יין\"\u0004 — \u0003הרי זה\u0004 (חבירו) \u0003יכול להפר את נדרו שלא על פי חכם. ויאמר לו: כלום אמרת\u0004 (נדרת) \u0003אלא מפני כבודי\u0004 שאתה רוצה לכבד אותי ולתת לבניי מתנה — \u0003זהו כבודי\u0004 שאינני לוקח, ואין כאן עוד נדר.","\u0003וכן האומר לחבירו \"קונם שאת נהנית לי אם אין את בא ונותן לבני כור של חטין ושתי חביות של יין\", ר' מאיר אומר: אסור\u0004 בהנאתו \u0003עד שיתן, וחכמים אומרים: אף זה\u0004 הנודר \u0003יכול להפר את נדרו שלא על פי חכם, ויאמר לו: הרי אני\u0004 נחשב \u0003כאילו נתקבלתי.\u0004","\u0003היה\u0004 חבירו \u0003מסרב\u0004 (מפציר) \u0003בו לשאת\u0004 את \u0003בת אחותו, ואמר\u0004 כדי לדחותו \u0003\"קונם שהיא נהנית לי לעולם\", וכן המגרש את אשתו\u0004 ו\u0003אומר \"קונם אשתי נהנית לי לעולם\" —\u0004 \u0003הרי אלו מותרות להנות לו, שלא נתכוון זה\u0004 לאיסור הנאה ממש \u0003אלא לשום\u0004 (לשם) הנאת \u0003אישות,\u0004 שנדר שלא ישאנה. \u0003היה מסרב\u0004 (מפציר) \u0003בחבירו שיאכל אצלו,\u0004 ו\u0003אמר\u0004 החבר: \u0003\"קונם לביתך שאני נכנס, טיפת צונן שאני טועם לך\"\u0004 — בכל זאת \u0003מותר ליכנס לביתו ולשתות ממנו צונן, שלא נתכוון זה\u0004 בדבריו \u0003אלא לשום\u0004 (לשם) \u0003אכילה ושתיה\u0004.","",""],["\u0003ר' אליעזר אומר:\u0004 כאשר באים חכמים להתיר נדר, \u0003פותחין לאדם בכבוד אביו ואמו.\u0004 שאומרים לו: אילו ידעת שהדבר גורם לבזות את הוריך שיש להם בן הנוהג קלות ראש ונודר, האם היית נודר? \u0003וחכמים\u0004 חולקים על ר' אליעזר ו\u0003אוסרין\u0004 לעשות כן.","\u0003אמר ר' צדוק\u0004 כסיוע לדברי חכמים: \u0003עד\u0004 (במקום) \u0003שפותחין לו בכבוד אביו ואמו יפתחו לו בכבוד המקום\u0004 (הקדוש ברוך הוא), וכבוד המקום הוא שלא ידור נדרים והוא בנדרו גרם לפגיעה בכבוד המקום, ו\u0003אם כן —\u0004 \u0003אין נדרים!\u0004 אולם \u0003מודים חכמים לר' אליעזר בדבר ש\u0004נדר \u0003בינו לבין אביו ואמו שפותחין לו בכבוד אביו ואמו,\u0004 מאחר שפתח זה שייך לגופו של הנדר.","\u0003ועוד אמר ר' אליעזר: פותחין בנולד, וחכמים אוסרין. כיצד\u0004 הוא \"נולד\"? \u0003אמר \"קונם שאני נהנה לאיש פלוני\" ו\u0004אחר זמן \u0003נעשה\u0004 אותו אדם \u0003סופר\u0004 (חכם, או לבלר, או מלמד תינוקות) שהוא נזקק לו, \u0003או שהיה\u0004 המודר \u0003משיא את בנו\u0004 ועורך סעודה לכל בני העיר, \u0003ואמר: אילו הייתי יודע שהוא נעשה סופר או שהיה משיא את בנו בקרוב לא הייתי נודר.\u0004","או שאמר \u0003\"קונם לבית זה שאני נכנס\" ונעשה\u0004 אחר כך אותו בית \u0003בית הכנסת, אמר: \"אילו הייתי יודע שהוא נעשה בית הכנסת לא הייתי נודר\".\u0004 בכל אלה \u0003ר' אליעזר מתיר, וחכמים אוסרין.\u0004","שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש דברי ר' צדוק \u0003\"\u0004אם כן \u0003אין נדרים\"? אמר אביי:\u0004 הכוונה היא: \u0003אם כן אין נדרים ניתרין יפה.\u0004 שמפני שמאיימים על הנודר ואומרים לו שהנדר עצמו יש בו צד עבירה וזלזול בכבוד המקום, הוא אומר שמתחרט על הנדר, אף שבאמת אינו חוזר בו מכוונתו הראשונה, ונמצא שאין היתר אמיתי וראוי לנדר."],["\u0003ורבא אמר: אם כן אין נדרים נשאלין לחכם,\u0004 שאם היו פותחים בפתח זה, המתאים לכל הנדרים, יאמר כל אחד שהוא יכול לפתוח פתח לעצמו, ואינו הולך עוד לחכם. ומאחר ואין אדם יכול להתיר לעצמו בפתח כזה — נמצא שאינו מותר על ידי כך.","ומבררים דעת חכמים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 : \u0003ומודין חכמים לר' אליעזר בדבר שבינו לבין אביו ואמו שפותחים לו בכבוד אביו ואמו. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי\u0004 ש\u0003אמר: אם כן אין נדרים ניתרין\u0004 יפה — \u0003הכא\u0004 \u0005[כאן]\u0006, \u0003כיון דאיחצף ליה\u0004 \u0005[שהתחצף לו]\u0006 בכך שנדר איסור מאביו ואמו — \u0003הא איחצף ליה\u0004 \u0005[הרי התחצף לו]\u0006 ואינו חושש לכבודם, לכן גם אין חוששים שרק בגלל כבודם יעמיד פנים כאילו הוא חוזר בו.","\u0003אלא לרבא,\u0004 ש\u0003אמר: אם כן אין נדרים נשאלין לחכם, הכא\u0004 \u0005[כאן]\u0006 בנדר מאביו ואמו \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פותחין?\u0004 ומשיבים: \u0003אמרי\u0004 \u0005[אומרים]\u0006 : \u0003כיון\u0004 ש\u0003כל נדרי לא סגיא להון דלאו\u0004 \u0005[הנדרים אין די להם בלא]\u0006 \u0003חכם,\u0004 שהרי לדעת חכמים אין פותחים בכבוד אביו ואמו בנדרים אחרים, וצריך החכם למצוא פתח אחר להתיר — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003פותחין\u0004 בכבוד אביו, ואין חוששים שמא יתיר נדרים לעצמו, שהרי אין זה היתר כללי, אלא היתר השייך לעצם הנדר הזה.","שנינו במשנה: \u0003ועוד אמר ר' אליעזר פותחין בנולד\u0004 וחכמים אוסרים. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר? אמר רב חסדא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 שאמר ה' למשה במדין שעתה יכול הוא לחזור למצרים למרות שנדר בשעתו ליתרו שלא ישוב למצרים \u0003\"כי מתו כל האנשים\u0004 המבקשים את נפשך\u0003\"\u0004 (שמות ד, יט). \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מיתה\u0004 ש\u0003נולד הוא,\u0004 כלומר, מצב חדש שלא היה קודם לכן, ו\u0003מכאן שפותחין בנולד. ו\u0004שואלים:","\u0003רבנן מאי טעמייהו\u0004 \u0005[וחכמים מה טעמם,\u0006 מה ישיבו להוכחה זו\u0005]?\u0006 ומשיבים: \u0003קסברי\u0004 \u0005[סבורים\u0006 הם\u0005]:\u0006 \u0003הנהו מי מייתי\u0004 \u0005[אלה,\u0006 מבקשי נפשו \u0005האם מתו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: כל מקום שנאמר\u0004 בתורה \u0003\"נצים\"\u0004 (שמות ב, יג) והם האנשים שהלשינו על משה, \u0003ו\"נצבים\"\u0004 האמור באלה שהתריסו כלפי משה ואהרן (שמות ה, כ), \u0003אינן אלא דתן ואבירם.\u0004 משמע שהיו עדיין חיים ויצאו עם האחרים ממצרים! \u0003אלא אמר ריש לקיש:\u0004 לא מתו ממש, אלא \u0003שירדו מנכסיהן\u0004 ולא התחשבו עוד בדבריהם, ומשום כך יכול היה משה לשוב למצרים ואין זה בגדר \"נולד\".","אגב כך מביאים מה ש\u0003אמר ר' יהושע בן לוי: כל אדם שאין לו בנים, חשוב כמת,\u0004 וראיה לדבר \u0003שנאמר\u0004 בדברי רחל ליעקב: \u0003\"הבה לי בנים ואם אין מתה אנכי\"\u0004 (בראשית ל, א). \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003ארבעה חשובין\u0004 (נחשבים) \u0003כמת: עני, ומצורע, וסומא\u0004 (עיוור), \u0003ומי שאין לו בנים. עני —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי מתו כל האנשים\"\u0004 ולא מתו ממש אלא שירדו מנכסיהם, ונחשבים כמתים. \u0003מצורע —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי אהרן למשה לגבי מרים שנצטרעה: \u0003\"אל נא תהי כמת\"\u0004 (במדבר יב, יב). \u0003וסומא —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במחשכים הושיבני כמתי עולם\"\u0004 (איכה ג, ו). \u0003ומי שאין לו בנים —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הבה לי בנים ואם אין מתה אנכי\".\u0004"],["\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 : \u0003המודר הנאה מחבירו —\u0004 \u0003אין מתירין לו\u0004 את נדרו \u0003אלא בפניו\u0004 של חבירו. שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006? \u0003אמר רב נחמן: דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ה' אל משה במדין לך שב מצרים כי מתו כל האנשים\u0004 המבקשים את נפשך\u0003\"\u0004 (שמות ד, יט), \u0003אמר לו\u0004 ה' למשה: \u0003במדין נדרת\u0004 ליתרו שלא תחזור למצרים — \u0003לך והתר נדרך במדין.\u0004 ומניין שנדר? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויואל משה\u0004 לשבת את האיש\u0003\"\u0004 (שמות ב, כא) ומפרשים \"ויואל\" — מלשון \"אלה\", ו\u0003אין אלה אלא שבועה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבא אתו באלה\"\u0004 (יחזקאל יז, יג).","וראיה אחרת לעצם ההלכה שאין מתירים אלא בפניו, שנאמר בצדקיהו המלך: \u0003\"וגם במלך נבוכדנאצר מרד אשר השביעו באלהים (חיים)\"\u0004 (דברי הימים ב לו, יג). ושואלים: \u0003מאי מרדותיה\u0004 \u0005[מה\u0006 היתה \u0005מרידתו]\u0006? ומשיבים: \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003צדקיה לנבוכדנצר דהוה קאכיל ארנבא\u0004 \u0005[שהיה אוכל ארנבת]\u0006 \u0003חיה\u0004 והתבייש נבוכדנצר בדבר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003אישתבע לי דלא מגלית עילוי ולא תיפוק מילתא\u0004 \u0005[הישבע לי שלא תגלה עלי ולא יצא הדבר\u0006 לרבים\u0005].\u0006 \u0003אישתבע\u0004 \u0005[נשבע]\u0006 לו.","\u0003לסוף הוה קא מצטער\u0004 \u0005[היה מצטער]\u0006 \u0003צדקיהו בגופיה\u0004 \u0005[בגופו,\u0006 בעצמו\u0005],\u0006 מפני שרצה לספר ולא יכול היה מפני השבועה שנשבע. \u0003איתשיל אשבועתיה\u0004 \u0005[נשאל על שבועתו]\u0006 לפני חכמים והתירו לו, \u0003ואמר,\u0004 וסיפר את הדבר ברבים. \u0003שמע נבוכדנצר דקא מבזין ליה\u0004 \u0005[שמבזים אותו]\u0006 בגלל מה שעשה. \u0003שלח ואייתי\u0004 \u0005[והביא]\u0006 \u0003סנהדרין וצדקיהו\u0004 לפניו. \u0003אמר להון\u0004 \u0005[להם]\u0006 לסנהדרין: \u0003חזיתון מאי קא עביד\u0004 \u0005[ראיתם מה עשה]\u0006 \u0003צדקיהו? לאו הכי אישתבע בשמא דשמיא ד\"לא מגלינא\"\u0004 \u0005[\u0006וכי \u0005לא כך נשבע בשם שמים \"שאיני מגלה\"]\u0006? \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 : \u0003איתשלי אשבועתא\u0004 \u0005[נשאל על השבועה].\u0006","\u0003[אמר להון\u0004 \u0005[להם]\u0006 : \u0003מתשלין אשבועתא\u0004 \u0005[\u0006וכי \u0005נשאלים על השבועה]\u0006?\u0003]\u0004 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בפניו\u0004 של האיש שנשבע לו נשאלים, \u0003או אפילו שלא בפניו? אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003בפניו\u0004 דווקא. \u0003אמר להון\u0004 \u0005[להם]:\u0006 \u0003ואתון מאי עבדיתון\u0004 \u0005[ואתם מה עשיתם],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמריתון\u0004 \u0005[אמרתם]\u0006 \u0003לצדקיהו\u0004 שאינו יכול להישאל על נדרו אלא בפני? \u0003מיד\u0004 נתקיים בהם \u0003\"ישבו לארץ ידמו זקני בת ציון\"\u0004 (איכה ב, י). \u0003אמר ר' יצחק: ששמטו כרים\u0004 שהיו יושבים עליהם כדיינים \u0003מתחתיהם,\u0004 להורות ששגו בדבר הלכה.","בהמשך לדברי חכמים במשנה הקודמת שאין פותחים בנולד, \u0003ר' מאיר אומר: יש דברים שהן כנולד ואינן\u0004 בעצם \u0003כנולד, ואין חכמים מודים לו. כיצד? אמר \"קונם שאני נושא את פלונית שאביה רע\" אמרו לו: מת\u0004 אביה, \u0003או שעשה תשובה.\u0004 או שאמר \u0003\"קונם לבית זה שאני נכנס שהכלב רע בתוכו, או שהנחש בתוכו\" אמרו לו: מת הכלב, או שנהרג הנחש —\u0004 \u0003הרי הן כנולד,\u0004 ובכל זאת \u0003אינו כנולד,\u0004 ופותחים בהם. \u0003ואין חכמים מודים לו.\u0004","שנינו במשנה שלדעת ר' מאיר יש דבר שהוא דומה לנולד ואינו נולד, כגון שנדר \u0003\"קונם שאני נכנס לבית זה שהכלב\u0004 רע בתוכו או שהנחש בתוכו \u0003\",\u0004 שאם מת הכלב הרי זה אינו כנולד. ותוהים: הלוא \u0003מת\u0004 ודאי \u0003נולד הוא!\u0004 שלא היה הדבר כן בשעת הנדר, ומדוע אומר ר' מאיר שאינו כנולד? \u0003אמר רב הונא: נעשה כתולה נדרו בדבר,\u0004 כלומר, אנו מבינים את נדרו כנדר על תנאי, שכל עוד קיים הכלב לא יכנס לבית, שכיון שפירש ואמר שמפני זה נדר, הרי כאשר נשתנה המצב — בטל הנדר. \u0003ור' יוחנן אמר:\u0004 הכוונה היא שכך פותחים לו: \u0003כבר מת\u0004 הכלב \u0003וכבר עשה\u0004 האב \u0003תשובה\u0004 לפני שנדר, \u0003קאמרי ליה\u0004 \u0005[אומרים לו]\u0006 לנודר, שנמצא שהיה זה נדר טעות מעיקרו."],["\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אבא\u0004 מן המשנה להלן: אמר \u0003\"קונם שאיני נושא לפלונית\u0004 שהיא \u0003כעורה\", והרי היא נאה,\u0004 או שאמר \u0003\"\u0004קונם שאיני נושא את פלונית לפי שהיא \u0003שחורה\", והרי היא לבנה,\u0004 או \u0003\"קצרה\",\u0004 (נמוכה) \u0003והרי היא ארוכה\u0004 (גבוהה) — \u0003מותר בה. לא מפני שכעורה ונעשת נאה,\u0004 או \u0003שחורה ונעשת לבנה,\u0004 או \u0003קצרה ונעשת ארוכה —\u0004 \u0003אלא שהנדר\u0004 היה \u0003טעות\u0004 מתחילתו. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרב הונא\u0004 ש\u0003אמר נעשה כתולה נדרו בדבר,\u0004 אם כן \u0003תנא\u0004 \u0005[שנה]\u0006 במשנתנו מקרה של \u0003תולה נדרו בדבר,\u0004 שאף שנדר כראוי אלא היה זה על תנאי שאכן היא כעורה וכדומה, \u0003ותנא\u0004 \u0005[ושנה]\u0006 גם \u0003נדר טעות. אלא ל\u0004דעת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 שיש להסביר שנדרו בטל משום שאומרים לו שעוד בטרם נדר \u0003כבר מת\u0004 הכלב \u0003וכבר עשה\u0004 האב \u0003תשובה,\u0004 אם כן \u0003למה לי למתני תרי זימני\u0004 \u0005[לשנות שתי פעמים]\u0006 \u0003נדר טעות?\u0004 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003ועוד אמר ר' מאיר: פותחין לו\u0004 לאדם בהתרת הנדר \u0003מן הכתוב שבתורה, ואומרין לו: אילו היית יודע ש\u0004על ידי הנדר שאתה עושה \u0003אתה עובר על \"לא תקם\"\u0004 (ויקרא יט, יח), או \u0003על \"לא תטר\"\u0004 (ויקרא יט, יח), או \u0003על \"לא תשנא את אחיך בלבבך\"\u0004 (ויקרא יט, יז), או על \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח). וכן על \u0003\"וחי אחיך עמך\"\u0004 (ויקרא כה, לו) \u0003שהוא\u0004 (המודר) \u0003עני ואין אתה יכול לפרנסו\u0004 בגלל הנדר שנדרת. אם \u0003אמר\u0004 הנודר: \u0003אילו הייתי יודע שהוא כן,\u0004 שיש בכך איסורים אלה, \u0003לא הייתי נודר\u0004 — במקרה זה \u0003הרי זה מותר.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא בר רב קטינא לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003נימא\u0004 \u0005[\u0006ש\u0005יאמר]\u0006 הנודר לגבי הטענה האחרונה: \u0003כל\u0004 מי \u0003דמעני\u0004 \u0005[שנעשה עני]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003עלי\u0004 הוא \u0003נפיל\u0004 \u0005[נופל]\u0006 ולא דווקא אני צריך לדאוג לו. \u0003מאי דמטי לי\u0004 \u0005[מה שמוטל עלי]\u0006 \u0003לפרנסו בהדי כולי עלמא מפרנסנא ליה\u0004 \u0005[יחד עם שאר אנשים אפרנס אותו]\u0006 כשאני נותן מעות לגבאי הצדקה. \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אני אומר כל הנופל\u0004 לעניות ונזקק לעזרה \u0003אינו נופל\u0004 ונזקק \u0003לידי גבאי\u0004 צדקה \u0003תחלה,\u0004 אלא קודם מתרושש מעט, ובאותו זמן אפשר עדיין לתמוך בו בעזרה אישית כדי שלא יגיע לידי עניות גמורה.","\u0003פותחין לאדם בכתובת אשתו,\u0004 שאם על ידי נדרו (כגון שנדר ממנה הנאה) יצטרך לגרש את אשתו, פותחים לו במה שלא העלה בדעתו כמה יקשה עליו לשלם את כתובתה.","\u0003ומעשה באחד שנדר מאשתו הנאה והיתה כתובתה ארבע מאות דינרים. ובא לפני ר' עקיבא וחייבו ליתן לה כתובתה. אמר לו: רבי, שמונה מאות דינרין הניח אבא\u0004 בירושה. \u0003נטל אחי ארבע מאות\u0004 מהם, \u0003ואני ארבע מאות. לא דיה\u0004 לאשתי \u0003שתטול היא מאתים ואני מאתים? אמר לו ר' עקיבא:\u0004 אין טענה זו מועילה, \u0003אפילו אתה מוכר שער ראשך —\u0004 \u0003אתה נותן לה כתובתה. אמר לו: אילו הייתי יודע שהוא כן,\u0004 שאני צריך לתת לה את כל רכושי — \u0003לא הייתי נודר. והתירה ר' עקיבא\u0004 להנות מנכסי בעלה.","על הביטוי שאמר ר' עקיבא \"אתה מוכר שער ראשך\" תוהים: \u0003מטלטלי מי משתעבדי\u0004 \u0005[מטלטלים האם\u0006 הם \u0005משתעבדים]\u0006 \u0003ל\u0004פרעון \u0003כתובה? אמר אביי:\u0004 מדובר כאן שירש מאביו \u0003קרקע שוה שמונה מאות דינר.\u0004 ומקשים: \u0003והקתני\u0004 \u0005[והרי הוא שונה]\u0006 \u0003\"שער ראשו\", ושער ראשו מטלטלי\u0004 \u0005[מטלטלים]\u0006 \u0003הוא!\u0004 ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 את הכתובה חייב אתה לתת (מן הקרקע), ו\u0003אפילו\u0004 על ידי כך תגיע למצב בו \u0003אתה מוכר שער ראשך ואוכל\u0004 משום שאין לך מקור אחר לפרנסה.","ושואלים: האם \u0003שמעת מינה\u0004 \u0005[שומע אתה מכאן]\u0006 כי \u0003אין מסדרין לבעל חוב,\u0004 שגובים הכל מן החייב, ואין עושים הסדר עם הנושים שישאירו לו מעט כדי שיוכל להתקיים? ודוחים: \u0003אמר רב נחמן בר' יצחק:\u0004"],["באמת מסדרים לבעל חוב, אבל באו דברי ר' עקיבא \u0003לומר שאין מקרעין שטר כתובה,\u0004 שגם כאשר בפועל משאירים לו מעט כדי חייו, מכל מקום החוב נשאר בעינו, וכאשר יהיה לו רכוש שאפשר יהיה להיפרע ממנו — יטלו ממנו.","\u0003פותחין בימים טובים ובשבתות,\u0004 שאם נדר מלאכול או מלשתות במשך תקופה מסויימת שואלים אותו אם העלה על דעתו בשעת הנדר שייאסר באכילה או בשתייה גם בימים אלה. \u0003בראשונה היו אומרים: אותן הימים\u0004 שאמר שלא התכוון להם — \u0003מותרין, ושאר כל הימים אסורין. עד שבא ר' עקיבא ולימד: שהנדר שהותר מכללו —\u0004 \u0003הותר כולו.\u0004","\u0003כיצד? אמר\u0004 לחבורה של אנשים \u0003\"קונם שאיני נהנה לכולכם\",\u0004 אם \u0003הותר אחד מהן\u0004 מכל סיבה שהיא — \u0003הותרו כולן.\u0004","אבל אם אמר \u0003\"שאיני נהנה לזה ולזה\",\u0004 אם \u0003הותר הראשון —\u0004 \u0003הותרו כולן,\u0004 אבל אם \u0003הותר האחרון —\u0004 \u0003האחרון\u0004 לבדו \u0003מותר וכולן אסורין,\u0004 כיון שכל אחד הוא נדר בפני עצמו. \u0003הותר האמצעי, הימנו ולמטה,\u0004 כל מי שמנה אחריו — \u0003מותר, הימנו ולמעלה,\u0004 שמנה לפניו — \u0003אסור.\u0004","אם אמר \u0003\"שאני נהנה לזה קרבן\u0004 (שאסור עלי כקרבן מה שאני נהנה לזה) \u0003ולזה קרבן\" —\u0004 \u0003צריכין פתח לכל אחד ואחד,\u0004 שיש פה נדר נבדל לכל אחד ואחד.","וכן בענין נדר שהותר מכללו, אם אמר \u0003\"קונם יין שאני טועם\u0004 מפני \u0003שהיין רע למעיים\", אמרו לו: והלא\u0004 היין \u0003המיושן יפה למעיים! —\u0004 \u0003הותר במיושן. ולא ב\u0004יין \u0003מיושן בלבד הותר אלא בכל\u0004 סוגי \u0003היין\u0004 הותר — שכיון שהותר מקצת הנדר הותר כולו. וכן אם אמר \u0003\"קונם בצל שאיני טועם\u0004 מפני \u0003שהבצל רע ללב\", אמרו לו: הלא\u0004 הבצל \u0003הכופרי יפה ללב! —\u0004 \u0003הותר ב\u0004בצל ה\u0003כופרי. ולא בכופרי בלבד הותר, אלא בכל הבצלים.\u0004 ומספרים: \u0003מעשה\u0004 שכזה \u0003היה והתירו ר' מאיר בכל הבצלים.\u0004","שנינו במשנה: \u0003הותר האחרון —\u0004 \u0003האחרון מותר וכולן אסורין\u0004 וכו'. ועוד שנינו: \"שאני נהנה לזה קרבן ולזה קרבן\" — צריכים פתח לכל אחד ואחד. ושואלים: \u0003מאן\u0004 \u0005[מי]\u0006 ה\u0003תנא\u0004 ששנה משנה זו?","\u0003אמר רבא:\u0004 שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 שאם נשבע אדם שבועת שקר לכמה אנשים כאחד, אין חייב קרבן על כל שבועה \u0003עד שיאמר\u0004 לשון \u0003\"שבועה\" לכל אחד ואחד.\u0004 ואם אמר לשון שבועה אחת, אף שפרט לכל אחד (\"לא לך, לא לך\") הרי זו נחשבת כשבועה אחת בלבד. ואף לענין נדרים כן, שרק כשאמר לשון \"קרבן\" לכל אחד, צריך פתח לכל אחד ואחד. ואם לאו הרי נחשב הדבר כנדר אחד.","שנינו במשנה: \u0003\"קונם יין שאני טועם\u0004 שהיין רע למעיים \u0003\",\u0004 ואמרו לו: \"הלא היין המיושן יפה למעיים\". ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 התרה רק מזה ש\u0003אין\u0004 היין המיושן \u0003רע\u0004 למעיים ודי בכך שאינו רע, והרי זה נדר טעות ויהא הנדר מותר אפילו אם לא היה יפה למעיים! \u0003אמר ר' אבא: ועוד, \"יפה\" קתני\u0004 \u0005[שנה].\u0006 כלומר, גם אם לא היה רע ולא יפה היה די בכך כדי להתיר, אלא הוסיפו ואמרו לו שהוא אפילו יפה למעיים.","עוד שנינו במשנה: \u0003\"קונם בצל שאני טועם שהבצל\u0004 רע ללב \u0003\",\u0004 ואמרו לו: \"הלא הכופרי יפה ללב\" וכו'. ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 התרה רק מזה ש\u0003אין\u0004 הבצל הכופרי \u0003רע\u0004 ואפילו אם אין הוא מועיל ללב! \u0003אמר ר' אבא: ועוד, \"יפה\" קתני\u0004 \u0005[שנה].\u0006 שאין זו אלא תוספת, שבאמת לא רק שאינו רע אלא גם יפה ללב.","\u0003פותחין לאדם\u0004 שצריך לגרש את אשתו מחמת נדר שנדר \u0003בכבוד עצמו ובכבוד בניו.\u0004 כיצד? \u0003אומרים לו: אילו היית יודע שלמחר\u0004 יהיו \u0003אומרין עליך\u0004 האנשים \u0003\"כך היא ווסתו\u0004 (מנהגו, דרכו) \u0003של פלוני —\u0004 שהוא \u0003מגרש את נשיו\u0004 בגלל נדרים \u0003\",\u0004 \u0003ועל בנותיך יהו אומרין \"בנות\u0004 נשים \u0003גרושות הן\",\u0004 או שיהיו אנשים שואלים \u0003\"מה ראתה אמן של אלו להתגרש\"\u0004 ויבואו להוציא שם רע על ילדיו. \u0003ואמר\u0004 הנודר: \u0003\"אילו הייתי יודע שכן\u0004 יאמרו — \u0003לא הייתי נודר\" —\u0004 \u0003הרי זה מותר.\u0004","אם אמר \u0003\"קונם שאני נושא את פלונית\u0004 לפי שהיא \u0003כעורה\" והרי היא נאה,\u0004 או אמר שאינו נושא אותה מפני שהיא \u0003שחורה והרי היא לבנה,\u0004 או מפני שהיא \u0003קצרה\u0004 (נמוכה) \u0003והרי היא ארוכה\u0004 (גבוהה) — \u0003מותר בה.\u0004 ומעירים: \u0003לא מפני שהיא כעורה ונעשת\u0004 לאחר זמן \u0003נאה,\u0004 או \u0003שחורה ונעשת לבנה,\u0004 או \u0003קצרה ונעשת ארוכה, אלא שהנדר\u0004 היה מתחילה נדר \u0003טעות.\u0004","\u0003ו\u0004מסופר \u0003מעשה באחד שנדר מבת אחותו הנייה\u0004 (הנאה) ולא רצה לשאתה, \u0003והכניסוה לבית ר' ישמעאל וייפוה.\u0004 ולאחר מכן הביאוה לפניו, \u0003אמר לו ר' ישמעאל: בני, מזו נדרת? אמר לו: לאו\u0004 \u0005[לא],\u0006 \u0003והתירה ר' ישמעאל,\u0004 שראה בזה נדר טעות.","\u0003באותה שעה בכה ר' ישמעאל ואמר: בנות ישראל נאות הן, אלא שהעניות מנוולתן\u0004 (מכערת אותן). \u0003וכשמת ר' ישמעאל היו בנות ישראל נושאות קינה, ואומרות: \"בנות ישראל על ר' ישמעאל בכינה\", וכן הוא אומר בשאול\u0004 שגם הוא דאג לבנות ישראל: \u0003\"בנות ישראל על שאול בכינה\u0004 המלבישכם שני עם עדנים המעלה עדי זהב על לבושכן\u0003\"\u0004 (שמואל ב א, כד).","שואלים: וכי מביאים \u0003מעשה\u0004 זה בר' ישמעאל שייפה את הנערה כדי \u0003לסתור\u0004 את הדברים שנאמרו קודם?! והרי אמרו שאם היתה כעורה ונעשית אחר כך נאה אין הנדר מותר! ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 ה\u0005יא שנויה]\u0006 : \u0003ר' ישמעאל אומר אפילו כעורה ונעשת נאה, שחורה ונעשת לבנה, קצרה ונעשת ארוכה —\u0004 מותרת על ידי פתח זה. ואכן אירע \u0003מעשה באחד שנדר מבת אחותו והכניסוה לבית ר' ישמעאל וייפוה וכו'.\u0004"],["\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 : \u0003שן תותבת היתה לה\u0004 והיתה מכערת אותה \u0003ועשה לה ר' ישמעאל שן של זהב משלו,\u0004 ועל ידי כך נתייפתה. \u0003כי שכיב\u0004 \u0005[כשמת]\u0006 \u0003ר' ישמעאל פתח עליה ההוא ספדנא הכי\u0004 \u0005[עליו ספדן אחד\u0006 בתחילת הספדו \u0005כך]\u0006 : \u0003\"בנות ישראל על ר' ישמעאל בכינה המלבישכן\" וכו'.\u0004 מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר לה לדביתהו\u0004 \u0005[לאשתו]\u0006 \u0003\"קונם שאי\u0004 (שאין) \u0003את נהנית לי עד שתטעימי תבשילך לר' יהודה ולר' שמעון\",\u0004 שיראו כמה גרוע את מבשלת. הלכה והטעימתם מתבשילה. \u0003ר' יהודה טעים\u0004 \u0005[טעם]\u0006 ולא חשש לכבודו, \u0003אמר: קל וחומר\u0004 הוא; \u0003ומה\u0004 כדי \u0003לעשות שלום בין איש לאשתו\u0004 בזמן שחושד בה הבעל שהיא סוטה \u0003אמרה תורה: שמי שנכתב בקדושה ימחה על המים המאררים\u0004 רק \u0003בספק, ואני על אחת כמה וכמה\u0004 צריך למחול על כבודי כדי לעשות שלום ביניהם. \u0003ר' שמעון לא טעים\u0004 \u0005[טעם],\u0006 \u0003אמר: ימותו כל בני אלמנה, ואל יזוז שמעון ממקומו.\u0004 כלומר, יכול הבעל למות ולהשאיר את אשתו אלמנה ובניו יתומים, וגם הם ימותו, ובלבד שלא יזלזלו אנשים בכבוד חכמים. \u0003ועוד\u0004 טעם יש בדבר שלא טעם: \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לתרגלי למינדר\u0004 \u0005[יתרגלו\u0006 אנשים \u0005לידור\u0006 נדרים\u0005].\u0006 ועוד מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר לדביתהו\u0004 \u0005[לאשתו]\u0006 \u0003\"קונם שאי\u0004 (שאין) \u0003את נהנית לי עד שתרוקי בו ברבן שמעון בן גמליאל\". אתת ורקק אלבושיה\u0004 \u0005[באה וירקה על לבושו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: והא האי לזילותא קא מיכוין\u0004 \u0005[והרי זה\u0006 האיש \u0005לבזיון\u0006 של רבן שמעון בן גמליאל \u0005התכוון]\u0006 ויריקה במלבושים איננה זלזול, ואם כן הריהי עדיין אסורה בהנאתו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003מירק\u0004 \u0005[לירוק]\u0006 \u0003על מני\u0004 \u0005[בגדי]\u0006 \u0003רבן שמעון בן גמליאל זילותא רבתא היא\u0004 \u0005[ביזיון גדול הוא]\u0006 ויצאה בכך. ומסופר עוד: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר לדביתהו\u0004 \u0005[לאשתו]\u0006 \u0003\"קונם שאי את נהנית לי עד שתראי מום\u0004 (מאום, דבר) \u0003יפה שביך\u0004 (שבך) \u0003לר' ישמעאל בר' יוסי\".\u0004","","","","","\u0003אמר להם\u0004 ר' ישמעאל לתלמידים כשרצה לחפש בה דבר יפה: \u0003שמא ראשה נאה? אמרו לו: סגלגל\u0004 (עגול) הוא. הוסיף לשאול: \u0003שמא שערה נאה?\u0004 אמרו לו: \u0003דומה\u0004 השיער \u0003לאניצי פשתן.\u0004 שאל עוד: \u0003שמא עיניה נאות?\u0004 אמרו לו: \u0003טרוטות\u0004 (צרות) \u0003הן.\u0004 \u0003שמא אזניה נאות?\u0004 אמרו לו: \u0003כפולות הן\u0004 וגדולות. \u0003שמא חוטמה נאה?\u0004 אמרו לו: \u0003בלום\u0004 (עבה וקצר) \u0003הוא. שמא שפתותיה נאות?\u0004 אמרו לו: \u0003עבות הן. שמא צוארה נאה?\u0004 אמרו לו: \u0003שקוט\u0004 (נמוך וקצר) \u0003הוא. שמא כריסה נאה?\u0004 אמרו לו: \u0003צבה\u0004 (נפוח) \u0003הוא. שמא רגליה נאות?\u0004 אמרו לו: \u0003רחבות כשל אווזא\u0004 (אווז). \u0003שמא שמה נאה?\u0004 אמרו לו: \u0003\"לכלוכית\" שמה. אמר להן: יפה קורין אותה לכלוכית, שהיא מלוכלכת במומין, ושרייה\u0004 \u0005[והתיר אותה]\u0006 מפני שאמר שיש בה משהו יפה — ששמה מתאים לה.","ועוד מסופר: \u0003ההוא בר\u0004 \u0005[\u0006אדם \u0005אחד בן]\u0006 \u0003בבל דסליק לארעא דישראל\u0004 \u0005[שעלה לארץ ישראל]\u0006 \u0003נסיב איתתא\u0004 \u0005[נשא\u0006 שם \u0005אשה].\u0006 \u0003אמר לה: בשילי\u0004 \u0005[בשלי]\u0006 \u0003לי תרי טלפי\u0004 \u0005[שתי עדשים],\u0006 כלומר, מעט עדשים. \u0003בשילה ליה תרי טלפי\u0004 \u0005[בישלה לו\u0006 בדיוק \u0005שתי עדשים].\u0006 \u0003רתח עלה\u0004 \u0005[כעס עליה].\u0006 \u0003למחר\u0004 כדי לתקן את הדבר \u0003אמר לה: בשילי\u0004 \u0005[בשלי]\u0006 \u0003לי גריוא\u0004 \u0005[סאה],\u0006 כלומר, הרבה עדשים. \u0003בשילה ליה גריוא\u0004 \u0005[בישלה לו סאה]\u0006 שיש בה הרבה מעבר לסעודתו של אדם. \u0003אמר לה: זילי אייתי\u0004 \u0005[לכי הביאי]\u0006 \u0003לי תרי בוציני\u0004 \u0005[שתי דלעות קטנות]\u0006, שבבבל קוראים לדלעת \"בוצינא\". \u0003אזלת ואייתי ליה תרי שרגי\u0004 \u0005[הלכה והביאה לו שני נרות]\u0006, כי בארץ ישראל קראו לנר \"בוצינא\". כעס ו\u0003אמר לה: זילי תברי יתהון על רישא דבבא\u0004 \u0005[לכי,\u0006 ו\u0005שברי אותן על ראש השער].\u0006 והיא לא הבינה לשון זו. באותה שעה \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 החכם \u0003בבא בן בוטא אבבא וקא דאין דינא\u0004 \u0005[בשער, והיה דן דין]\u0006 \u0003אזלת ותברת יתהון על רישיה\u0004 \u0005[הלכה ושברה אותן על ראשו]\u0006 שהיה שמו בבא. \u0003אמר לה: מה הדין דעבדת\u0004 \u0005[מה זה שעשית]\u0006? \u0003אמרה ליה\u0004 \u0005[לו]\u0006 : \u0003כך ציוני בעלי. אמר: את עשית רצון בעליך —\u0004 אם כך \u0003המקום\u0004 (הקדוש ברוך הוא) \u0003יוציא ממך שני בנים\u0004 (כנגד שני הנרות) \u0003כבבא בן בוטא.\u0004","","","\u0003נערה המאורסה, אביה ובעלה\u0004 (ארוסה) יחד \u0003מפירין\u0004 את \u0003נדריה.\u0004"],["אם \u0003הפר האב ולא הפר הבעל\u0004 (הארוס), או ש\u0003הפר הבעל ולא הפר האב\u0004 — הנדר \u0003אינו מופר. ואין צריך לומר\u0004 אם \u0003קיים אחד מהן\u0004 את הנדר שאף אם הפר לה האחר, הנדר קיים.","על מה שנאמר במשנה הפר האב ולא הפר הבעל אין הנדר מופר, תוהים: \u0003היינו רישא\u0004 \u0005[\u0006הרי \u0005זוהי ההתחלה]\u0006 ששנינו בה: \u0003אביה ובעלה\u0004 (ארוסה) \u0003מפירין נדריה!\u0004 ומשיבים: יש צורך בדבר, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ש\u0003או אביה או בעלה\u0004 מפירים נדריה \u0003קתני\u0004 \u0005[שנה],\u0006 ו\"אביה ובעלה\" משמעו — כל אחד מהם לחוד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהכוונה היא לשניהם יחד.","שנינו במשנה \u0003\"ואין צריך לומר ש\u0004נדרה קיים אם \u0003קיים\u0004 לה \u0003אחד מהן\".\u0004 שואלים: \u0003למה לי למיתנא\u0004 \u0005[לשנות]\u0006 זאת? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003יש לומר\u0004 אם \u0003הפר זה בלא זה —\u0004 \u0003ולא כלום,\u0004 אינו נחשב כהפרה, אם כן כאשר \u0003קיים אחד מהן למה לי?\u0004 וכי דבר זה \u0003צריכא למיתני\u0004 \u0005[צריך לשנות]?\u0006","ומשיבים: \u0003כי איצטריך ליה\u0004 \u0005[כאשר הוצרך לו]\u0006 דין זה הרי הוא במקרה \u0003כגון\u0004 ש\u0003הפר אחד מהן וקיים אחד, וחזר המקיים ונשאל\u0004 לחכם \u0003על הקמתו,\u0004 ומבטל את מה שקיים. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מאי דאוקי הא עקריה\u0004 \u0005[\u0006את \u0005מה שהקים הרי עקר אותו]\u0006 על ידי השאלה לחכם, ואם כן אין כאן כבר נדר ודי במה שהפר השני, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003מפירין שניהם בבת אחת,\u0004 כלומר, רק על ידי הפרה של שניהם.","לאחר בירור סגנון המשנה שואלים לגופה של ההלכה: דין זה ש\u0003נערה המאורסה אביה ובעלה מפירין\u0004 את \u0003נדריה, מנלן\u0004 \u0005[מניין לנו]?\u0006 שכיון שהיא עדיין בבית אביה, די שיפר לה הוא לבדו! \u0003אמר רבה, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואם היו תהיה לאיש ונדריה עליה...\u0004 ואם ביום שמוע אישה... (במדבר ל, ז. במדבר ל, ט), \u0003מכאן לנערה המאורסה שאביה ובעלה\u0004 (ארוסה) \u0003מפירין נדריה.\u0004 ושואלים: \u0003אימא האי קרא\u0004 \u0005[אמור\u0006 ש\u0005כתוב זה]\u0006 דווקא \u0003ב\u0004אשה \u0003נשואה כתיב\u0004 \u0005[נאמר]!\u0006","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום נשואה, קרא אחרינא כתיב\u0004 \u0005[כתוב אחר נאמר]\u0006 \u0003\"ואם בית אישה נדרה\"\u0004 (במדבר ל, יא). ומסתבר שהפסוקים הקודמים מדברים בארוסה, שעדיין אינה מצויה בבית בעלה. ושואלים: \u0003אימא תרוייהו\u0004 \u0005[אמור\u0006 ש\u0005שניהם]\u0006 מדברים \u0003בנשואה?! וכי תימא תרי קראי\u0004 \u0005[ואם תאמר שני כתובים]\u0006 באשה \u0003נשואה למה לי\u0004 — אפשר לפרש שבא הכתוב הנוסף \u0003למימר\u0004 \u0005[לומר]\u0006 לנו \u0003שאין הבעל מיפר בקודמין,\u0004 שאינו יכול להפר נדרים שנדרה לפני נישואיה, אלא רק באלה שב\"בית אשה נדרה\"."],["\u0003ולאו\u0004 \u0005[והאם לא]\u0006 \u0003ממילא,\u0004 מכלל הדברים \u0003שמעת מינה\u0004 \u0005[לומד אתה\u0006 זאת\u0005]\u0006? שהרי נאמר \"אם בית אישה נדרה\", ומשמע שנדרים שנדרה קודם לכן אינו יכול להפר.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ראיה אחרת, ממה שהכתוב \"אם היו תהיה לאיש\" מדבר בארוסה, כי לשון של \u0003הויה\u0004 (\"תהיה לאיש\") \u0003קדושין משמע\u0004 ולא נישואין.","ולעצם הענין שואלים: \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003אב לחודיה\u0004 \u0005[לבדו]\u0006 \u0003מיפר\u0004 נדרי בתו המאורסה! ומשיבים: \u0003אם כן\u0004 מה שנאמר בכתוב \u0003\"ואסרה אסר בית אביה\"\u0004 (במדבר ל, ד) ונאמר על כך \u0003\"יניא אותה\"\u0004 (במדבר ל, ט) \u0003למה לי? השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 לשיטתך \u0003יש לומר\u0004 ש\u0003במקום\u0004 שיש \u0003ארוס מיפר אב לחודיה\u0004 \u0005[לבדו]\u0006, \u0003שלא במקום ארוס,\u0004 כלומר, כשאינה ארוסה, \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שהוא מפר?","ושואלים מצד אחר: \u0003אימא\u0004 \u0005[אמור]\u0006 שה\u0003אב ליבעי\u0004 \u0005[שיצטרך]\u0006 שגם ה\u0003ארוס\u0004 יפר עימו, \u0003וארוס לחודיה\u0004 \u0005[לבדו]\u0006 \u0003מיפר.\u0004 \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אב דכתב רחמנא\u0004 \u0005[שכתבה התורה],\u0006 וכפי שלמדנו מסמיכות הכתובים, \u0003למה לי,\u0004 אם הארוס יכול להפר לבדו — אפשר היה לומר כי \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 ללמד \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003הקים\u0004 האב את הנדר — \u0003הקים,\u0004 ואין הארוס יכול להפר!","ודוחים: \u0003אם כן \"בית אישה נדרה\"\u0004 (במדבר ל, יא) האמור באשה נשואה \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה צורך\u0005]\u0006 \u0003כתב\u0004 אותו? הלא \u0003קל וחומר\u0004 הוא: \u0003ומה במקום\u0004 שיש \u0003אב, ארוס מיפר לחודיה\u0004 \u0005[לבדו],\u0006 \u0003שלא במקום אב\u0004 כשהיא נשואה שאינה ברשות אביה \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שמפר?!","וממשיכים לשאול עוד: \u0003אימא\u0004 \u0005[אמור]\u0006 שהארוס לבדו יכול להפר, והכתוב \u0003\"אם בית אישה נדרה\"\u0004 לא נועד לומר לנו שהבעל מפר לבדו, אלא לצמצם את כוחו \u0003לומר שאין הבעל מיפר בקודמין!\u0004","ומשיבים: \u0003ומיניה\u0004 \u0005[וממנו]\u0006 מדבר זה עצמו יכול אתה לחזור וללמוד את ההלכה, שהרי משאלה זו אפשר להסיק ש\u0003ארוס\u0004 כן \u0003מיפר בקודמין.\u0004 ומדוע יוכל הארוס, שאין האשה לגמרי ברשותו, לעשות מה שאין הבעל יכול לעשות?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום שותפותיה\u0004 \u0005[שותפותו]\u0006 של ה\u0003אב\u0004 שמיפר יחד איתו, כיון שבאב אין הגבלה כזו, ויכול להפר גם בקודמים. ומכאן אנו למדים שהארוס לבדו אינו יכול להפר כלל."],["\u0003דבי\u0004 \u0005[\u0006החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 מקור אחר לדין משנתנו: נאמר בפרשת הנדרים שבתורה \"אלה החוקים... \u0003בין איש לאשתו בין אב לבתו\u0004 בנעוריה בית אביה\" (במדבר ל, יז), שאינו ענין לנשואה, שעניינה נתפרש קודם לכן, אלא מדבר הכתוב בארוסה, \u0003מכאן לנערה המאורסה שאביה ובעלה\u0004 (ארוסה) \u0003מפירין נדריה\u0004 ואז מתקיים בה הכתוב בשלימותו. ושואלים: \u0003ול\u0004דעת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 הלומד דין נערה מאורסה מכאן, הכתוב \"ו \u0003אם היו תהיה לאיש\"\u0004 (במדבר ל, ז) ממנו למדנו דין זה למעלה \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]\u0006?","ומשיבים: \u0003מוקים לאידך\u0004 \u0005[מעמיד אותו ל\u0006צורך הדבר ה\u0005אחר]\u0006 שאמר \u0003רבא,\u0004 שבכל מקום שמת הארוס ולא קיים את הנדר, יכול האב לבדו להפר. ושואלים: \u0003ורבא\u0004 הלומד בנערה המאורסה שאביה ובעלה מפירים נדריה מ\"ואם היו תהיה לאיש\", \u0003האי דתני\u0004 \u0005[זה ששנה],\u0006 כלומר, כתוב זה שדרש אותו החכם \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]\u0006? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003לומר שהבעל מיפר\u0004 רק \u0003נדרים שבינו לבינה\u0004 שיש להם שייכות ליחסים שביניהם, ולא כל נדר שהיא נודרת, ולכן ההדגשה \"בין איש לאשתו\".","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003בעל\u0004 (ארוס) שמפר את נדרה של ארוסתו, האם בכך \u0003מיגז גייז\u0004 \u0005[גוזז,\u0006 חותך\u0005]\u0006 הוא לגמרי חלק מן הנדר, \u0003או\u0004 שהוא \u0003מקליש\u0004 \u0003קליש\u0004 \u0005[מקליש,\u0006 מחליש\u0005]\u0006 את כוחו של הנדר כולו? ומסבירים: \u0003היכא קא מיבעיא לן\u0004 \u0005[היכן נשאלה לנו]\u0006 שאלה זו, כלומר, באיזה מקרה יש הבדל מעשי בין הדברים? \u0003כגון\u0004 ש\u0003נדרה מתרין זיתין\u0004 \u0005[משני זיתים]\u0006 \u0003ושמע\u0004 ה\u0003ארוס והיפר לה\u0004 את נדרה, \u0003ואכלתנון\u0004 \u0005[ו\u0006היא \u0005אכלה אותם\u0006 את שני הזיתים\u0005].\u0006","\u0003אי אמרינן מיגז גייז\u0004 \u0005[אם אומרים אנו\u0006 שהוא \u0005גוזז]\u0006 את האיסור, כלומר, מתיר חצי מן האיסור, נמצא שעדיין חל איסור גמור על זית אחד מתוך השניים שנדרה עליהם, ולכן \u0003לקייא\u0004 \u0005[\u0006הריהי \u0005לוקה]\u0006 מפני שעברה על הנדר. ו\u0003אי אמרינן מקליש קליש\u0004 \u0005[אם אומרים אנו\u0006 שהוא \u0005מקליש,\u0006 מחליש\u0005]\u0006 את תוקפו של כל הנדר, נמצא שאין כאן עוד נדר שלם, ואין כאן חיוב מלקות אלא \u0003איסורא בעלמא\u0004 \u0005[איסור בלבד]\u0006 \u0003הוא.\u0004 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 : \u0003אימתי אמרו\u0004 שאם \u0003מת הבעל\u0004 (הארוס) \u0003נתרוקנה רשות לאב,\u0004 שיכול להפר את נדריה לבדו — \u0003בזמן שלא שמע הבעל\u0004 את נדרה \u0003קודם שימות, או ששמע ושתק, או ששמע והפר ומת בו ביום. זו,\u0004 כלומר, במקרה זה, \u0003היא ששנינו: מת הבעל נתרוקנה רשות לאב.\u0004"],["\u0003אבל אם שמע\u0004 הבעל \u0003וקיים\u0004 את הנדר, \u0003או ששמע ושתק ומת ביום שלאחריו,\u0004 שעצם שתיקתו היא כקיום — \u0003אין\u0004 האב \u0003יכול להפר.\u0004","\u0003שמע אביה והפר לה, ולא הספיק\u0004 ה\u0003בעל לשמוע עד שמת האב —\u0004 \u0003זו היא ששנינו: מת האב לא נתרוקנה רשות לבעל\u0004 (לארוס), שאין הארוס יכול להפר לבדו כאשר האב אינו מצטרף עימו. \u0003שמע בעלה והפר לה, ולא הספיק האב לשמוע עד שמת הבעל —\u0004 \u0003זו היא ששנינו: מת הבעל נתרוקנה רשות לאב\u0004 שדי בהפרת האב לבדו.","\u0003שמע בעלה והפר לה, ולא הספיק האב לשמוע עד שמת —\u0004 \u0003אין הבעל יכול להפר,\u0004 למרות שעכשיו אין לה אב, \u0003שאין הבעל מיפר אלא בשותפות.\u0004"],["\u0003שמע אביה והפר לה, ולא הספיק הבעל\u0004 (הארוס) \u0003לשמוע עד שמת —\u0004 \u0003חוזר האב ומפר חלקו של בעל\u0004 ואינו צריך לשוב ולהפר את חלקו. \u0003אמר ר' נתן:\u0004 דברים אלו \u0003הן הן דברי בית שמאי.\u0004 ואילו \u0003בית הלל אומרים: אין יכול להפר,\u0004 אלא צריך לחזור ולהפר גם את חלקו שלו.","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 : ש\u0003ל\u0004דעת \u0003בית שמאי מיגז גייז\u0004 \u0005[\u0006הוא \u0005חותך]\u0006 חצי מן הנדר ולכן יכול האב לחזור ולהפר מה שלא הפר הבעל, כלומר את החצי השני. ואילו \u0003ל\u0004דעת \u0003בית הלל\u0004 הוא רק \u0003מקלש קליש\u0004 \u0005[מחליש\u0006 את תוקפו\u0005]\u0006 ולכן אין האב יכול להפר בשלימות את חלק הבעל. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא, והלכה כבית הלל.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: יש שאלה בהקם,\u0004 האם יכול אדם להישאל לחכם ולבטל את מה שקיים את נדרה של אשתו או בתו, \u0003או אין שאלה בהקם?\u0004 ועוד, \u0003אם תמצא לומר\u0004 ש\u0003יש שאלה בהקם\u0004 ויכול להישאל על מה שקיים את נדרה של אשתו, האם \u0003יש שאלה בהפר,\u0004 שאם הפר את נדר אשתו האם יכול להישאל לחכם על כך ולחזור ולקיים, \u0003או אין שאלה בהפר?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלות אלה ממה ש\u0003אמר ר' יוחנן: נשאלין על ההקם,\u0004 שאם קיים את הנדר יכול להישאל על מה שהקים אותו, \u0003ואין נשאלין על ההפר.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה:\u0004 אמר לאשה לאחר ששמע את נדרה \u0003\"קיים ליכי\u0004 \u0005[לך]\u0006 נדרך, \u0003קיים ליכי\u0004 \u0005[לך]\u0006 נדרך \u0003\"\u0004שתי פעמים, \u0003ונשאל\u0004 לחכם \u0003על הקמה ראשונה\u0004 וביטלה, ולא נשאל על השניה, \u0003מהו\u0004 הדין? האם הנדר בטל משום שביטל את ההקמה, או שמא כיון שלא ביטל את ההקמה השניה — הנדר נשאר קיים.","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר רבא\u0004 לענין הנשבע \"שבועה שלא אוכל, שבועה שלא אוכל\": \u0003אם נשאל על הראשונה —\u0004 \u0003שניה חלה עליו.\u0004 ומכאן תלמד לענייננו שכל עוד לא ביטל את ההקמה השניה, עדיין נשאר הנדר קיים. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה:\u0004 אם אמר לאשה \u0003\"קיים ליכי\u0004 \u0005[לך]\u0006 הנדר, \u0003ומופר ליכי\u0004 \u0005[לך]\u0006 \u0003ולא תיחול\u0004 (תחול) \u0003הקמה אלא אם כן חלה הפרה\" מהו\u0004 הדין?"],["\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר \u0003מפלוגתא\u0004 \u0005[מהמחלוקת]\u0006 של \u0003ר' מאיר ור' יוסי. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 : אמר על בהמה \u0003\"הרי זו תמורת עולה תמורת שלמים\" —\u0004 \u0003הרי זו\u0004 נעשית \u0003תמורת עולה\u0004 בלבד, אלו \u0003דברי ר' מאיר\u0004 שהולכים אחרי דיבורו הראשון. \u0003ור' יוסי אומר: אם לכך נתכוין מתחלה\u0004 שתהיה זו תמורה של עולה ושלמים יחד, \u0003הואיל ואי אפשר לקרות\u0004 (לקרוא) \u0003שני שמות כאחד,\u0004 שהרי אינו יכול להגיד עולה ושלמים בדיבור אחד — \u0003דבריו קיימין.\u0004","ומוסיפים: \u0003ואפילו ר' מאיר לא קאמר\u0004 \u0005[אומר]\u0006 שהולכים אחר הלשון הראשונה אלא כשאומר שני דברים שאינם תלויים זה בזה, ש\u0003לא אמר \"לא תיחול זו אלא אם כן חלה זו\", אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003אמר\u0004 במפורש \u0003\"לא תיחול הקמה אלא אם כן חלה הפרה\" —\u0004 \u0003ר' מאיר נמי\u0004 \u0005[גם כן]\u0006 \u0003מודה\u0004 ש\u0003הפרה חלה,\u0004 ואין הולכים אחר ההקמה בלבד.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה:\u0004 אם אמר \u0003\"קיים ומופר ליכי\u0004 \u0005[לך]\u0006 \u0003\"\u0004\u0003בבת אחת מהו?\u0004 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר רבה\u0004 עצמו: כאשר אדם רוצה להחיל כאחד שני דברים, \u0003כל דבר שאינו\u0004 יכול לחול \u0003בזה אחר זה,\u0004 הרי \u0003אפילו\u0004 כשמחיל אותו \u0003בבת אחת אינו\u0004 חל, ובטל כולו. ולכן אף כאן, כיון שאינו יכול לקיים ולהפר בזה אחר זה, אם כן גם כשאמר אותם בבת אחת — אין דבריו חלים.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה:\u0004 אמר לאשתו \u0003\"קיים ליכי\u0004 \u0005[לך]\u0006 נדרך \u0003היום\", מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 : הרי זה \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003אמר לה \"מופר ליכי\u0004 \u0005[לך]\u0006 נדרך \u0003למחר\", או דלמא\u0004 \u0005[שמא]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא אמר לה\u0004 במפורש שהנדר מופר?"],["\u0003אם\u0004 תפתור בעיה זו בשלילה, ו\u0003תמצא לומר הא\u0004 \u0005[הרי]\u0006 \u0003לא אמר לה\u0004 במפורש שהוא מפר למחר, אם \u0003אמר לה \"מופר ליכי\u0004 \u0005[לך]\u0006 נדרך \u0003למחר\" מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 : \u0003למחר לא מצי מיפר\u0004 \u0005[יכול להפר]\u0006 \u0003דהא קיימיה לנדריה\u0004 \u0005[שהרי קיים\u0006 כבר \u0005את נדרו]\u0006 \u0003היום\u0004 על ידי ששתק כל היום, \u0003או דלמא\u0004 \u0005[שמא]\u0006 : \u0003כיון\u0004 ש\u0003לא אמר לה\u0004 במפורש \u0003\"קיים ליכי\u0004 \u0005[לך]\u0006 נדרך \u0003היום\", כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003לה \"מופר ליכי\u0004 \u0005[לך]\u0006 נדרך \u0003למחר\" מהיום קאמר\u0004 \u0005[\u0006הוא \u0005אומר]\u0006 ומתכוון להפר.","\u0003ואם תמצא לומר\u0004 ש\u0003אפילו הכי\u0004 \u0005[כך]\u0006, \u0003כיון\u0004 ש\u0003קיימו היום,\u0004 שהרי אמר שיהא מופר רק מחר — \u0003למחר כמאן דאיתיה דמי\u0004 \u0005[כמי שישנו,\u0006 הנדר, \u0005נחשב]\u0006 ואינו יכול להפר אותו, אם \u0003אמר לה \"קיים ליכי\u0004 \u0005[לך]\u0006 נדרך \u0003שעה\" מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 : \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003אמר לה \"מופר ליכי\u0004 \u0005[לך]\u0006 \u0003לאחר שעה\" דמי\u0004 \u0005[נחשב]\u0006, \u0003או דלמא\u0004 \u0005[שמא]\u0006 : \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא אמר לה\u0004 במפורש שיהיה מופר לה לאחר שעה?","\u0003אם תמצא לומר הא\u0004 \u0005[הרי]\u0006 \u0003לא אמר לה\u0004 ואינו מופר לאחר שעה, \u0003מיהו\u0004 \u0005[מכל מקום]\u0006 אם \u0003אמר לה\u0004 במפורש שהוא מופר לאחר שעה \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 : נדר זה \u0003כיון\u0004 ש\u0003קיימו —\u0004 \u0003קיימו\u0004 ושוב אינו יכול להפר אותו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 : \u0003כיון דכוליה יומא\u0004 \u0005[שכל היום\u0006 כולו\u0005]\u0006 הוא \u0003בר\u0004 \u0005[בן]\u0006 \u0003הקמה ובר\u0004 \u0005[ובן]\u0006 \u0003הפרה\u0004 שבאותו יום יכול להחליט אם להקים או להפר, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר \"מופר ליכי\u0004 \u0005[לך]\u0006 \u0003לאחר שעה\" מהני\u0004 \u0005[מועיל\u0006 הדבר\u0005]\u0006?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו שאם אמרה אשה \u0003\"הריני נזירה\", ושמע בעלה ואמר \"ואני\",\u0004 כלומר, גם אני אהיה נזיר — \u0003אין יכול להפר\u0004 עוד את נדרה של אשתו. ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006? \u0003נימא\u0004 \u0005[נאמר]\u0006 כך בכוונת דבריו: \u0003\"ואני\"\u0004 ש\u0003אמר הוא על נפשיה\u0004 \u0005[עצמו]\u0006 \u0003דהוי\u0004 \u0005[שהוא]\u0006 \u0003נזיר,\u0004 ונדר זה בודאי קיים, \u0003אבל \"הריני נזירה\" דילה\u0004 \u0005[שלה]\u0006 במשך \u0003שעה אחת קיימא\u0004 \u0005[קיים\u0006 הנדר\u0005]\u0006 ומשום כך יכול אז להתפיס בו גם את נדר הנזירות שלו, אבל \u0003לאחר שעה אי בעי\u0004 \u0005[אם ירצה] —\u0006 \u0003ליפר\u0004 \u0005[יפר]\u0006, ואם כן, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אנו אומרים ש\u0003אין יכול להפר? לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003כיון שקיימו\u0004 שעה אחת — \u0003קיימו\u0004 לעולם, ושוב אין לו הפרה? ודוחים: \u0003לא, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 : \u0003כל\u0004 שאומר \u0003\"ואני\" —\u0004 \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]\u0006 \u0003\"קיים ליכי\u0004 \u0005[לך]\u0006 נדרך \u0003לעולם\" דמי\u0004 \u0005[נחשב].\u0006 ולפיכך נשארו כל השאלות הללו ללא פתרון.","אם \u0003מת האב —\u0004 \u0003לא נתרוקנה רשות\u0004 האב \u0003לבעל\u0004 (לארוס), שאין הארוס מקבל את כל הזכות להפר לבדו את נדריה. אבל אם \u0003מת הבעל —\u0004 \u0003נתרוקנה רשות לאב\u0004 ויכול להפר לבדו. \u0003בזה יפה כח האב מכח הבעל.\u0004","ואילו \u0003בדבר אחר יפה כח הבעל מכח האב: שהבעל מפר בבגר,\u0004 כלומר, גם אם האשה היא בוגרת יכול הבעל להפר, ולא רק בנערותה, \u0003ו\u0004אילו \u0003האב אינו מפר בבגר,\u0004 שאין בכוחו להפר את נדריה של בתו אלא עד שתתבגר.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לא נתרוקנה רשות לבעל במות האב — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בנעריה בית אביה\"\u0004 (במדבר ל, יז), לומר שכל עוד היא נערה (\"בנעוריה\") אף שנתארסה, הריהי בעיקרה ברשות אביה, וגם אם מת האב — עדיין היא בבית אביה.","ושואלים: הלכה זו שאם \u0003מת הבעל נתרוקנה רשות לאב מנלן\u0004 \u0005[מניין לנו]\u0006? \u0003אמר רבה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואם היו תהיה לאיש ונדריה עליה\"\u0004 (במדבר ל, ז) —"],["\u0003מקיש\u0004 \u0005[משווה]\u0006 הכתוב נדרים \u0003קודמי הויה שניה,\u0004 שנדרה בהיותה קודם אירוסין (\"הויה\") שניים — לאחר שכבר נתארסה פעם, \u0003ל\u0004נדרים \u0003קודמי הויה ראשונה\u0004 קודם שנתארסה כלל; \u0003מה קודמי הויה ראשונה\u0004 מובן ש\u0003אב מיפר לחודיה\u0004 \u0005[לבדו],\u0006 \u0003אף קודמי הויה שניה,\u0004 אחרי שכבר נתארסה ונתגרשה או מת הארוס — \u0003אב מיפר לחודיה\u0004 \u0005[לבדו].\u0006","ושואלים: \u0003אימא הני מילי\u0004 \u0005[אמור\u0006 ש\u0005דברים אלה]\u0006 שהאב מפר לבד, אמורים \u0003בנדרים שלא נראו לארוס,\u0004 שהארוס לא שמע עליהם כלל, ולא היו ברשותו לקיים או להפר. \u0003אבל בנדרים שנראו לארוס —\u0004 \u0003לא מצי מיפר\u0004 \u0005[יכול להפר]\u0006 ה\u0003אב\u0004 לבדו!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 להשמיענו \u0003בנדרים שלא נראו לארוס\u0004 — זה אינו צריך ללימוד מיוחד, משום שדין זה \u0003מ\"בנעריה בית אביה\"\u0004 (במדבר ל, יז) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 לומר, שכל עוד היא בבית אביה רשאי אביה להפר את נדריה.","שנינו במשנה ש\u0003בזה יפה כח האב מכח הבעל,\u0004 שכאשר מת הארוס נתרוקנה רשותו לאב והוא מפר לבדו, מה שאין כן במת האב שלא נתרוקנה רשותו לארוס. ומאידך גיסא, יפה כוח הבעל מכוח האב, לפי שהאב אינו מפר את נדרי בתו הבוגרת ואילו הבעל מפר את נדרי אשתו אף כשהיא בוגרת. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]\u0006 שהבעל מפר כשהיא בוגרת?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שקידשה כשהיא נערה,\u0004 ונדרה, \u0003ובגרה. מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003מיתה\u0004 (מיתת האב) \u0003מוציאה\u0004 את הנערה מרשותו, \u0003ו\u0004גם \u0003בגרות מוציאה מרשות אב\u0004 יהא דינם שווה לענין נדרים: \u0003מה\u0004 על ידי \u0003מיתה\u0004 של האב \u0003לא נתרוקנה רשות לבעל,\u0004 שאם מת האב ולא הספיק להפר אין הארוס לבדו רשאי להפר, \u0003אף\u0004 כשהיא מגיעה ל\u0003בגרות —\u0004 \u0003לא נתרוקנה רשות\u0004 האב שהיתה לו בזמן הנערות \u0003לבעל!\u0004","\u0003אלא\u0004 תאמר \u0003שקידשה כשהיא בוגרת,\u0004 ונדרה — \u0003הא תנינא חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005שנינו\u0006 זאת \u0005פעם אחת]:\u0006 \u0003הבוגרת ששהתה,\u0004 שחלפו עליה, \u0003שנים עשר חדש\u0004 הניתנים לה לאחר אירוסיה כדי להכין את צורכי הנישואין, ומאז חייב הארוס במזונותיה, אף שלא כנסה עדיין בנישואין, שיש מי שאומר שהארוס לבדו יכול אז להפר לה. ולשם מה נשנית המשנה פעמיים?","ותחילה מעירים כי \u0003הא גופא קשיא\u0004 \u0005[זו,\u0006 המשנה \u0005עצמה קשה]:\u0006 \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 דין זה בענין \u0003הבוגרת ששהתה שנים עשר חדש,\u0004 ואולם \u0003בבוגרת למה לי שנים עשר חדש\u0004 של המתנה ושהייה עד לנישואין? הרי שנינו כי \u0003בוגרת בשלשים יום סגי\u0004 \u0005[די]\u0006 \u0003לה,\u0004 שמן הסתם כבר מתוקנים לה כל צורכי הנישואין, וזמן נישואיה (אם לא הוסכם אחרת) הוא בתוך שלושים יום! ומתקנים: \u0003תני\u0004 \u0005[שנה]:\u0006 או \u0003בוגרת\u0004 ששהתה שלושים יום, או נערה \u0003ששהתה שנים עשר חדש.\u0004","\u0003מכל מקום קשיא\u0004 \u0005[קשה],\u0006 שאם מדובר במשנתנו במקרה זה, נמצא ששנה פעמיים דין בוגרת! ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003הכא\u0004 \u0005[כאן\u0006 במשנתנו\u0005]\u0006 \u0003דוקא,\u0004 כאן הוא עיקר דין זה, \u0003ובוגרת קתני התם\u0004 \u0005[שנה שם]\u0006 רק \u0003משום דבעי איפלוגי\u0004 \u0005[שרצה\u0006 להביא את \u0005מחלוקת]\u0006 \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים]\u0006 בפרטי דין זה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003בוגרת\u0004 ששנה במשנה שם הוא \u0003דוקא,\u0004 ושם הוא עיקר ההלכה. \u0003ו\u0004מה שנשנה דין זה גם במשנתנו, יש להסביר: \u0003איידי דנסיב רישא\u0004 \u0005[אגב שהביא בראש\u0006 המשנה\u0005]\u0006 את הלשון \u0003\"בזה\"\u0004 (\"בזה יפה כוח האב\") — \u0003נסיב סיפא נמי\u0004 \u0005[הביא גם כן בסוף\u0006 המשנה\u0005]\u0006 את הלשון \u0003\"בזה\"\u0004 לגבי כוח הבעל, אבל עיקר הלכה זו שייך למשנה האחרת."],["\u0003נדרה והיא\u0004 באותה שעה \u0003ארוסה, ונתגרשה בו ביום\u0004 מארוסה זה, וחזרה ו\u0003נתארסה בו ביום\u0004 לאחר, \u0003אפילו\u0004 התארסה והתגרשה כך \u0003למאה\u0004 אנשים בזה אחר זה בו ביום — \u0003אביה ובעלה האחרון מפירין נדריה. זה הכלל: כל שלא יצאה לרשות עצמה\u0004 בנישואין או בבגרות \u0003שעה אחת —\u0004 \u0003אביה ובעלה האחרון מפירין נדריה.\u0004","שואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שה\u0003ארוס\u0004 ה\u0003אחרון מיפר נדרים שנראו\u0004 (שהיו כבר לפני) \u0003לארוס ראשון\u0004 ושמע אותם? \u0003אמר שמואל, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואם היו תהיה לאיש ונדריה עליה...\u0004 והפר את נדרה\u0003\"\u0004 (במדבר ל, ז. במדבר ל, ט), לומר שהארוס מפר את נדרי ארוסתו ולא רק את אלה שנדרה משנתארסה לו, אלא אף את ה\u0003נדרים שהיו עליה כבר\u0004 כשהיתה מאורסת לאחר. ושואלים: \u0003דלמא הני מילי\u0004 \u0005[שמא דברים אלה]\u0006 אמורים דווקא בנדרים \u0003שלא נראו לארוס ראשון\u0004 אף על פי שנדרה אותם קודם אירוסיה לאחרון, \u0003אבל נדרים שנראו לארוס ראשון\u0004 להפירם — \u0003לא מצי מיפר\u0004 \u0005[אין יכול להפר]\u0006 \u0003ארוס אחרון!\u0004","ומשיבים: מה שנאמר \u0003\"עליה\" קרא יתירא\u0004 \u0005[כתוב יתר]\u0006 \u0003הוא,\u0004 ובא ללמד שיכול להפר את כל הנדרים שעליה וגם את אלה שנראו לארוס ראשון.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמו\u0006 שיטתו] של \u0003שמואל:\u0004 \u0003נערה המאורסה —\u0004 \u0003אביה ובעלה\u0004 (ארוסה) \u0003מפירין נדריה, כיצד? שמע אביה והפר לה, ולא הספיק הבעל\u0004 (הארוס) \u0003לשמוע עד שמת, ונתארסה בו ביום\u0004 לאחר, \u0003ואפילו מאה פעמים\u0004 בזה אחר זה מת בעלה והתארסה לאחר בו ביום — \u0003אביה ובעלה האחרון מפירין נדריה. שמע בעלה והפר לה, ולא הספיק האב לשמוע עד שמת הבעל —\u0004 \u0003חוזר האב ומפר\u0004 את \u0003חלקו של\u0004 ה\u0003בעל.\u0004","\u0003אמר ר' נתן: הן הן דברי בית שמאי,\u0004 שלשיטתם כל אחד מהם מפר חצי מההפרה של הנערה המאורסה. \u0003אבל בית הלל אומרים: אין יכול להפר\u0004 לבדו אלא בצירוף ארוס שני. ועולה מכאן כדברי שמואל, שאף נדרים שנדרה בפני ארוס ראשון יכול ארוס שני להפר. ושואלים: \u0003במאי פליגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]\u0006 בית שמאי ובית הלל?"],["\u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003נדרים נמי\u0004 \u0005[גם כן]\u0006 \u0003שראוי\u0004 (שנראו) \u0003לארוס,\u0004 אם מת הארוס \u0003נתרוקנה רשות לאב\u0004 ובידו הרשות להפר את נדרי בתו, \u0003ומיגז גייז\u0004 \u0005[ו\u0006הוא \u0005חותך].\u0006 שאם האב או הארוס מפירים נדר הרי הם \"חותכים\" בכך חצי מן הנדר, ולכן יכול האב להפר את חלקו של הארוס שמת, כלומר, את החצי השני. ואילו \u0003בית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003אביה ובעלה אחרון מפירין נדריה, ולא מיגז גייז\u0004 \u0005[חותך]\u0006 המפר את הנדר, אלא הבעל או האב רק ממעטים (\"מקלישים\") את תוקפו של הנדר. וכאשר נראה הנדר לארוס ראשון, אין האב יכול לבטל לגמרי אף את חלקו של הארוס בנדר, אלא רק בשותפות עם ארוס אחר.","א \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 : האם \u0003גירושין\u0004 שמגרש בעל את אשתו לאחר שנדרה \u0003כשתיקה דמיא\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006, \u0003או כהקמה\u0004 (קיום הנדר) \u0003דמיא\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006?","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מה ההבדל למעשה הנובע מכאן? הלא מכל מקום לא הפר לה לפני שגירשה. ועכשיו, לאחר שגירשה — שוב אינו יכול להפר! ומשיבים: \u0003כגון שנדרה ושמע בעלה וגרשה, ואהדרה ביומיה\u0004 \u0005[והחזירה בו ביום].\u0006 \u0003אי אמר מר\u0004 \u0005[אם אומר החכם]\u0006 שהגירושין \u0003כשתיקה דמי\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006, אם כן \u0003מצי מיפר\u0004 \u0005[יכול להפר]\u0006 \u0003לה\u0004 כשנושא אותה שנית, שהרי לא קיים את הנדר, אלא רק המתין, ולאחר זמן ובו ביום — מפר אותו. \u0003ואי אמר מר\u0004 \u0005[ואם אומר החכם]\u0006 שהגירושין \u0003כהקמה דמי\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006, אם כן \u0003לא מצי מיפר\u0004 \u0005[אינו יכול להפר]\u0006 \u0003לה\u0004 עוד, שבמעשה הגירושין כאילו קיים את נדרה, ואז אינו יכול להפירו עוד."],["\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר מן הברייתא: \u0003אימתי אמרו \"מת הבעל\u0004 (הארוס) \u0003נתרוקנה רשות לאב\" —\u0004 \u0003בזמן שלא שמע הבעל, או שמע והפר, או שמע ושתק ומת בו ביום. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003גירושין כשתיקה דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006, \u0003ליתני נמי\u0004 \u0005[שישנה גם כן]\u0006 \u0003\"או שמע וגירש\"! מדלא תני הכי\u0004 \u0005[מ\u0006כיון \u0005שלא שנה כך] —\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003גירושין כהקמה דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006, ושוב האב אינו יכול להפר.","ודוחים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של הברייתא\u0005]\u0006 : \u0003אבל אם שמע וקיים, או שמע ושתק ומת ביום של אחריו —\u0004 \u0003אין יכול להפר. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003גירושין כהקמה דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006, \u0003ליתני\u0004 \u0005[שישנה]\u0006 גם \u0003\"ואם שמע וגירש\"! אלא\u0004 צריך אתה לומר להיפך, \u0003מדלא קתני הכי\u0004 \u0005[מ\u0006כיון \u0005שלא שנה כך]\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003גירושין כשתיקה דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006 ונמצא איפוא כי הדיוקים מן הרישא ומן הסיפא של הברייתא סותרים זה את זה.","\u0003אלא מהא ליכא למשמע מיניה\u0004 \u0005[מ\u0006ברייתא \u0005זו אין\u0006 אתה יכול \u0005לשמוע,\u0006 ללמוד \u0005ממנה]\u0006 בדרך הדיוק. אלא \u0003אי רישא דוקא\u0004 \u0005[אם ראשה מדוייק]\u0006 ומה שלא מנה גירושין בכלל הדינים מלמדנו שגירושין דינם כהקמה — צריך לומר כי \u0003נסיב סיפא\u0004 \u0005[הביא\u0006 את \u0005סופה]\u0006 \u0003משום רישא\u0004 \u0005[ראשה]\u0006 באותו סגנון בדיוק, ומשום כך לא מנה בה את כל המקרים האפשריים. או יכול אתה לפרש להיפך; \u0003אי סיפא דוקא\u0004 \u0005[אם סופה מדוייק]\u0006 וממה שלא מנה גירושין משמע שגירושין דינם כשתיקה, יש לכן לומר כי \u0003נסיב רישא\u0004 \u0005[הביא\u0006 את \u0005ראשה]\u0006 \u0003משום סיפא\u0004 \u0005[סופה]\u0006 באותו סגנון, ולא מנה את כל המקרים.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו \u0003נדרה והיא ארוסה, ונתגרשה ונתארסה בו ביום, אפילו למאה —\u0004 \u0003אביה ובעלה\u0004 (ארוסה) \u0003האחרון מפירין נדריה. שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003גירושין כשתיקה דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כהקמה\u0004 \u0003דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 \u0003מי מצי מיפר\u0004 \u0005[האם יכול להפר]\u0006 \u0003ארוס אחרון נידרי דאוקים\u0004 \u0005[נדרים שהקים\u0006 כבר\u0005]\u0006 ה\u0003ארוס ראשון?\u0004","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003ב\u0004מקרה \u0003שלא שמע\u0004 ה\u0003ארוס\u0004 ה\u0003ראשון\u0004 את נדרה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע שנה דווקא שאירע הדבר \u0003בו ביום? אפילו לאחר מאה ימים נמי\u0004 \u0005[גם כן]\u0006 יכול הארוס האחרון להפר. שכיון שלא שמע הארוס ביום שנדרה יכול להפר בכל זמן ששומע!","ומשיבים: מדובר שם \u0003כשלא שמע ארוס ושמע האב,\u0004 ובמקרה כזה \u0003בו ביום הוא דמצי מיפר\u0004 \u0005[שיכול להפר]\u0006, \u0003אבל מכאן ואילך לא מצי מיפר\u0004 \u0005[אינו יכול להפר],\u0006 שהרי כבר נשמע הנדר לאב, והארוס אינו יכול להפר ביום אחר. ומשום כך אין ללמוד מכאן שגירושין דינם כשתיקה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003נדרה בו ביום, גירשה והחזירה בו ביום —\u0004 \u0003אין יכול להפר. שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003גירושין כהקמה דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006","ודוחים, \u0003אמרי\u0004 \u0005[אומרים]\u0006 : \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004אשה \u0003נשואה עסקינן\u0004 \u0005[עוסקים אנו]\u0006, \u0003והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 ש\u0003אין יכול להפר,\u0004 לא משום שהוקם הנדר על ידי הגירושין, אלא \u0003משום\u0004 ש\u0003אין הבעל מיפר בקודמין\u0004 (בנדרים שקדמו לנישואיו) ולכן אינו יכול להפר אף נדר שנדרה בזמן נישואיו הראשונים עימה. ובסיכומו של דבר לא נמצא פתרון לשאלה."],["\u0003דרך תלמידי חכמים\u0004 לדאוג שלא יהיו כל נדרים על האשה הנישאת. וכיצד היו עושים; כשהיה האב תלמיד חכם, \u0003עד שלא\u0004 (בטרם) \u0003היתה בתו יוצאה מאצלו\u0004 בנישואיה \u0003אומר לה: כל נדרים שנדרת בתוך ביתי —\u0004 \u0003הרי הן מופרין. וכן הבעל\u0004 שהוא תלמיד חכם, \u0003עד שלא תכנס לרשותו\u0004 בעודה ארוסה, \u0003אומר לה: כל נדרים שנדרת עד שלא תכנסי לרשותי —\u0004 \u0003הרי הן מופרין.\u0004 משום \u0003שמשתכנס לרשותו —\u0004 \u0003אינו יכול להפר\u0004 את הנדרים שנדרה קודם לכן.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: בעל, מהו שיפר בלא שמיעה,\u0004 כלומר, בלא שידע שנדרה אשתו נדר מסויים? וצדדי השאלה: האם מה שנאמר בהפרת הבעל \u0003\"ושמע אישה\"\u0004 (במדבר ל, ח) \u0003דוקא\u0004 \u0005[מדוייק]\u0006 \u0003הוא,\u0004 שרק כאשר הוא שומע שנדרה יכול להפר, \u0003או לאו דוקא\u0004 \u0005[אינו מדוייק]\u0006 \u0003הוא\u0004 ויכול להפר אף בלא לשמוע, אלא שדיבר הכתוב בהווה, שלאחר ששומע שנדרה מפר לה?","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממשנתנו: \u0003דרך תלמידי חכמים עד שלא יצאת בתו מאצלו אומר לה: כל נדרים שנדרת בתוך ביתי הרי הן מופרין, והא\u0004 \u0005[והרי]\u0006 \u0003לא שמע!\u0004 מכאן, שאפשר להפר בלא שמיעה.","את הראיה הזו דוחים: אין הכוונה שנדרים שלא שמע יהיו מופרים עתה, אלא \u0003לכי שמע\u0004 \u0005[שכאשר הוא שומע]\u0006 \u0003הוא\u0004 ש\u0003מיפר,\u0004 שאמר מראש שכל נדר שישמע שנדרה — יפר אותו, ואינו מפר אלא לאחר שישמע. ומקשים: \u0003אם כן,\u0004 אם אין כאן הפרה עכשיו, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא שמע, למה ליה\u0004 \u0005[לו]\u0006 \u0003למימר\u0004 \u0005[לומר]\u0006 עכשיו שהנדר מופר? ימתין עד שישמע את נדרה! ומשיבים: \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003אורחיה דצורבא מרבנן להדורי\u0004 \u0005[דרכו של תלמיד חכם לחזר\u0006 ולבדוק\u0005]\u0006 ושמא מתוך מה שאמר לה תספר לו שנדרה, ואז יוכל להפר.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר \u0003מ\u0004מה ששנינו ב\u0003סיפא\u0004 \u0005[סופה\u0006 של המשנה\u0005]:\u0006 \u0003וכן הבעל, עד שלא תכנס לרשותו אומר לה:\u0004 כל נדרים שנדרת עד שלא תיכנסי לרשותי הרי הן מופרין. משמע שמפר אף בלא שמיעה! ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה \u0003דאמר\u0004 \u0005[שאומר]\u0006 הוא \u0003לה: לכי שמענא\u0004 \u0005[כאשר אשמע]\u0006 שנדרת נדר — הריהו מופר.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממקור אחר, ששנינו: \u0003האומר לאשתו \"כל נדרים שתדורי עד שאבא ממקום פלוני הרי הן קיימין\" —\u0004 \u0003לא אמר\u0004 בכך \u0003כלום,\u0004 ואין זה קיום. אם אמר לה שכל הנדרים שתידור עד אז \u0003הרי הן מופרין, ר' אליעזר אומר: מופר. והא\u0004 \u0005[והרי]\u0006 \u0003לא שמע.\u0004 אלא מכאן נדייק שכדי להפר אין צורך שישמע!","ודוחים: מכאן אין ראיה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לפרש \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003\"לכי שמענא\"\u0004 \u0005[כאשר אשמע]\u0006 יהיו מופרים. \u0003ו\u0004שואלים: אם כן \u0003למה לי\u0004 שיפר \u0003מן השתא\u0004 \u0005[מעכשיו]\u0006? \u0003לכי שמע ליפר\u0004 \u0005[כאשר ישמע יפר]\u0006 \u0003לה!\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003דלמא מטרידנא ההיא שעתא\u0004 \u0005[שמא אהיה טרוד באותה שעה]\u0006 ואשכח להפר. ולכן מפר מראש, ותחול ההפרה כאשר ישמע.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003האומר לאפוטרופוס\u0004 (ממונה) שהעמיד בביתו לטפל בצורכי הבית כשהוא נעדר מביתו: \u0003כל נדרים שנודרת אשתי מכאן ועד שאבא ממקום פלוני —\u0004 \u0003הפר, והפר לה\u0004 האפוטרופוס, \u0003יכול יהו מופרין —\u0004 \u0003תלמוד לומר: \"אישה יקימנו ואישה יפרנו\"\u0004 (במדבר ל, יד), שאין יכול להפר אלא בעלה לבדו. אלו \u0003דברי ר' יאשיה.\u0004","\u0003אמר לו ר' יונתן:\u0004 הלא \u0003מצינו\u0004 (מצאנו) \u0003בכל התורה כולה\u0004 כי \u0003שלוחו של אדם כמותו,\u0004 ומדוע לא יפר האפוטרופוס?","ולענייננו נלמד מכאן: \u0003ואפילו ר' יאשיה לא קאמר\u0004 \u0005[אינו אומר]\u0006 שאין אפוטרופוס מפר \u0003אלא משום\u0004 ש\u0003גזירת הכתוב הוא\u0004 שדווקא \u0003\"אישה יקימנו ואישה יפרנו\", אבל\u0004 מעיקר הדין \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 לולי גזירת הכתוב היינו אומרים כי \u0003שלוחו של אדם כמותו\u0004 אף בהפרת נדרים, והיה השליח יכול להפר לה. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא שמיע ליה\u0004 \u0005[שמע\u0006 הבעל \u0005עצמו]\u0006 עדיין את הנדרים! ומכאן ראיה שהבעל עצמו יכול להפר אף בלא לשמוע."],["\u0003הכא נמי דאמר ליה\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005שאומר לו]:\u0006 \u0003לכי שמענא מיפר\u0004 \u0005[כאשר אשמע\u0006 את הנדר יהיה \u0005מופר]\u0006 \u0003לה.\u0004 ומקשים: אם כן, \u0003לכי שמע ליפר\u0004 \u0005[כאשר ישמע יפר]\u0006 \u0003לה\u0004 ולמה לו להתנות מעכשיו? ומשיבים: \u0003הוא,\u0004 הבעל, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003דלמא מטרידנא\u0004 \u0005[שמא אהיה טרוד]\u0006 באותה שעה ואף אם אשמע אשכח להפר. ואם כן לא נפתרה השאלה.","בהמשך לשאלתו הראשונה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: חרש, מהו שיפר לאשתו?\u0004 שהרי גם \u0003אם תמצא לומר\u0004 בפתרון השאלה הראשונה ש\u0003בעל\u0004 אחר, שאינו חרש \u0003מיפר בלא שמיעה\u0004 — הרי יש טעם בדבר, \u0003משום דבר מישמע\u0004 \u0005[בן שמיעה]\u0006 \u0003הוא,\u0004 וגם אם אינו שומע בפועל, הריהו מסוגל לשמוע, \u0003אבל חרש דלאו בר מישמע\u0004 \u0005[שלא בן שמיעה]\u0006 \u0003הוא\u0004 ואינו יכול לשמוע כלל, שמא נאמר כי \u0003היינו\u0004 \u0005[זהו]\u0006 הכלל שקבע \u0003ר' זירא.\u0004","ש\u0003אמר ר' זירא:\u0004 במנחות, \u0003כל הראוי לבילה\u0004 (לבלילה) שכמות הסולת במנחה היא כזו שניתן לבלול אותה כראוי בבת אחת — \u0003אין בילה מעכבת בו,\u0004 שאף שלכתחילה צריך לבלול את הסולת והשמן, אין הדבר מעכב בדיעבד, אם לא היתה בלילה. \u0003וכל שאין ראוי לבילה\u0004 שמחמת ריבוי הכמות אי אפשר לבלול אותו — \u0003בילה מעכבת בו\u0004 ואינו כשר. ומכאן נובעת הלכה כללית, שגם דבר שאינו מעכב בדיעבד, מכל מקום צריך שיהיה ראוי לכך, ואולם מה שאינו ראוי כלל — פסול.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003\"ושמע אישה\"\u0004 (במדבר ל, ח) כלל \u0003לא מעכב\u0004 ומיפר בכל אופן?! \u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במדרש ההלכה על הכתוב \u0003\"ושמע אישה\"\u0004 — \u0003פרט לאשת חרש.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 : \u0003בעל, מהו שיפר לשתי נשיו בבת אחת?\u0004 וצדדי השאלה: האם נאמר כי הכתוב \u0003\"\u0004יניא \u0003אותה\"\u0004 (במדבר ל, ט) הוא \u0003דוקא\u0004 \u0005[מדוייק]\u0006, והכוונה לאשה אחת בלבד, \u0003או לאו דוקא\u0004 \u0005[אינו מדוייק]\u0006 ויכול להפר אף ליותר מאשה אחת בבת אחת?","\u0003אמר רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006, פתרון ממה ששנינו: \u0003אין משקין שתי סוטות כאחת\u0004 במים המרים, \u0003מפני שלבה\u0004 של האחת \u0003גס\u0004 (מתחזק) \u0003בחבירתה,\u0004 כלומר, על ידי שיש עימה אחרת שוב אינה מתביישת ומפחדת כל כך ואינה מודה על מה שעשתה.","\u0003ר' יהודה אומר: לא מן השם הוא זה,\u0004 אין זה טעם ועיקר הדין, \u0003אלא משום שנאמר \"והשקה\"\u0004 (במדבר ה, כז) במפיק בה\"א, כלומר, והשקה אותה. משמע: \u0003אותה, לבדה.\u0004 ולשיטת ר' יהודה אף לענייננו נלמד, שכיון שנאמר \"יניא אותה\" — משמעו אותה לבדה, ולא שתים כאחת."],["ארוסה \u0003בוגרת ששהתה שנים עשר חדש\u0004 לאחר שנתארסה ותבעה בעלה להינשא, \u0003ואלמנה\u0004 ששהתה \u0003שלשים יום, ר' אליעזר אומר: הואיל ובעלה\u0004 לאחר זמן זה \u0003חייב\u0004 כבר \u0003במזונותיה,\u0004 שאם לא נקבע מראש מועד קבוע לנישואין צריך לשאתה לאחר זמן זה, ואם לא עשה כן — מתחייב במזונותיה כאילו היתה כבר נשואה לו, משום כך אף \u0003יפר\u0004 את נדריה לבדו, כאילו היתה כבר נשואה לו. \u0003וחכמים אומרים: אין הבעל מיפר\u0004 לבדו \u0003עד שתכנס לרשותו.\u0004","\u0003אמר רבה: ר' אליעזר ומשנה ראשונה אמרו דבר אחד. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 : \u0003נותנין לבתולה שנים עשר חדש\u0004 משתבעה הבעל להינשא \u0003לפרנס עצמה\u0004 (להכין לעצמה את כל צורכי הנישואין) ולאחר מכן הוא הזמן הראוי לנישואין, וצריך הארוס לשאתה. \u0003הגיע שנים עשר חדש,\u0004 אף על פי שלא נשאה — \u0003אוכלת\u0004 האשה \u0003משלו,\u0004 כלומר, חייב במזונותיה, \u0003ו\u0004אם היתה ארוסת כהן — \u0003אוכלת בתרומה\u0004 ככל אשת כהן. \u0003אבל היבם\u0004 הכהן \u0003אינו מאכיל בתרומה\u0004 את האשה הזקוקה לו לייבום עד שיישאנה ממש.","\u0003עשתה ששה חדשים\u0004 של המתנה \u0003בפני הבעל\u0004 ומת הבעל, \u0003וששה חדשים\u0004 המתינה \u0003בפני היבם, ואפילו כולן בפני הבעל חסר יום אחד, או כולן בפני היבם חסר יום אחד —\u0004 \u0003אינה אוכלת בתרומה\u0004 עד שתמתין שנים עשר חודש אצל הבעל. \u0003זו\u0004 היתה שיטת \u0003משנה ראשונה. בית דין של אחריהם אמרו:\u0004 מפני חששות שונים \u0003אין האשה אוכלת בתרומה\u0004 \u0003עד שתכנס לחופה.\u0004 ומכאן שכשיטת משנה ראשונה סבור ר' אליעזר, שכשהגיע זמן הנישואין הרי זה כאילו היא נשואה ממש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא\u0004 \u0005[שמא]\u0006 \u0003לא היא\u0004 אותה שיטה; כי \u0003עד כאן לא קא אשמעינן\u0004 \u0005[השמיעה לנו]\u0006 \u0003משנה ראשונה אלא\u0004 שתהא האשה רשאית \u0003למיכל\u0004 \u0005[לאכול]\u0006 משהגיע הזמן \u0003בתרומה דרבנן\u0004 \u0005[שמדברי סופרים].\u0006 שהרי מדובר פה בתרומה בזמן הזה, שאין הפירות חייבים בתרומה מן התורה. \u0003אבל נדרים\u0004 שאיסורם הוא מ\u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יוכל להפר.","\u0003ו\u0004להיפך, \u0003עד כאן לא שמעת ליה\u0004 \u0005[אותו]\u0006 \u0003לר' אליעזר אלא גבי נדרים,\u0004 ואפשר לומר שהוא סבור כשמועתו של \u0003רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 ש\u0003אמר\u0004 ש\u0003כל הנודרת —\u0004 \u0003על דעת בעלה היא נודרת,\u0004 שכיון שהוא המפרנס אותה אינה נודרת אלא אם כן יסכים לכך. ואף כאן, כיון שהארוס חייב מעתה בפרנסתה — על דעתו היא נודרת. \u0003אבל\u0004 לענין \u0003תרומה\u0004 אפשר לומר בדעת ר' אליעזר כי \u0003אפילו\u0004 כשהוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003נמי לא אכלה\u0004 \u0005[גם כן אינה אוכלת].\u0006 ואם כן אין הוכחה ששיטות אלה מצטרפות יחד."]]};
